function diffLines(before, after) {
  const left = before.trimEnd().split("\n");
  const right = after.trimEnd().split("\n");
  let start = 0;
  while (start < left.length && start < right.length && left[start] === right[start]) start++;
  let end = 0;
  while (start + end < left.length && start + end < right.length &&
      left[left.length - end - 1] === right[right.length - end - 1]) end++;
  if (start === left.length && start === right.length) return "";
  const oldLines = left.slice(start, left.length - end);
  const newLines = right.slice(start, right.length - end);
  const lines = ["@@ from line " + (start + 1) + " @@"];
  const width = newLines.length + 1;
  const cells = (oldLines.length + 1) * width;
  if (cells > 2_000_000) {
    lines.push("Large comparison: changed range shown as two blocks.");
    for (const text of oldLines) lines.push("-" + text);
    for (const text of newLines) lines.push("+" + text);
    return lines.join("\n");
  }
  const matches = new Uint32Array(cells);
  for (let a = oldLines.length - 1; a >= 0; a--) {
    for (let b = newLines.length - 1; b >= 0; b--) {
      const at = a * width + b;
      matches[at] = oldLines[a] === newLines[b] ? 1 + matches[at + width + 1] :
        Math.max(matches[at + width], matches[at + 1]);
    }
  }
  for (let a = 0, b = 0; a < oldLines.length || b < newLines.length;) {
    if (a < oldLines.length && b < newLines.length && oldLines[a] === newLines[b]) {
      lines.push(" " + oldLines[a++]);
      b++;
    } else if (a < oldLines.length && (b === newLines.length ||
        matches[(a + 1) * width + b] >= matches[a * width + b + 1])) {
      lines.push("-" + oldLines[a++]);
    } else {
      lines.push("+" + newLines[b++]);
    }
  }
  return lines.join("\n");
}

function lineChange(before, after, language = "en") {
  const diff = diffLines(before, after);
  return diff ? codeFence(diff, "diff") : translate(language, "No converted Markdown body difference.");
}

function parentPath(path) {
  const lastSlash = path.lastIndexOf("/");
  return lastSlash === -1 ? "" : path.slice(0, lastSlash);
}

function ancestors(path, stop) {
  const result = [];
  for (let folder = parentPath(path); folder && folder !== stop; folder = parentPath(folder)) result.unshift(folder);
  return result;
}

function localSlug(text) {
  return normalized(text.trim().toLowerCase()).replace(/[^\p{L}\p{N}_ -]/gu, "").replace(/\s+/g, "-");
}

function visibleSourcePath(path, source) {
  return typeof path === "string" && path.startsWith(source + "/") &&
    path.slice(source.length + 1).split("/").every(part => part && !part.startsWith("."));
}

function vaultReference(reference, file, app, source) {
  const url = /^[a-z][a-z+.-]*:/i.test(reference.target) || reference.target.startsWith("//");
  if (url) return null;
  const [path, anchor] = reference.target.split("#", 2);
  let decoded;
  try {
    decoded = decodeURIComponent(path);
  } catch {
    return null;
  }
  const target = decoded ? app.metadataCache.getFirstLinkpathDest(decoded, file.path) : file;
  if (!target?.extension || !visibleSourcePath(target.path, source)) return null;
  try { return { file: target, anchor: anchor ? decodeURIComponent(anchor) : anchor }; } catch { return null; }
}

// Walk only the selected branch; never enumerate the vault-wide file registry.
function sourceMarkdownFiles(folder, source) {
  if (folder.path !== source || !Array.isArray(folder.children)) {
    throw new Error("The source folder hierarchy changed. Reload the review.");
  }
  const files = [];
  const stack = [folder];
  const seen = new Set([source]);
  while (stack.length) {
    const current = stack.pop();
    for (const child of current.children) {
      const path = child?.path;
      if (typeof path !== "string" || !path.startsWith(source + "/") || parentPath(path) !== current.path) {
        throw new Error("The source folder hierarchy changed. Reload the review.");
      }
      const name = path.slice(current.path.length + 1);
      if (name.startsWith(".")) continue;
      if (!name || seen.has(path)) throw new Error("The source folder hierarchy changed. Reload the review.");
      seen.add(path);
      if (Array.isArray(child.children)) stack.push(child);
      else if (typeof child.extension === "string" && child.extension.toLowerCase() === "md") files.push(child);
    }
  }
  return files;
}

function unchangedSourcePaths(note, source) {
  return note.file.path === note.path && visibleSourcePath(note.path, source) &&
    Array.from(note.assets, ([path, asset]) => asset.file.path === path && visibleSourcePath(path, source)).every(Boolean);
}

async function publicationInputHash(sourceHash, assetHashes, diagrams) {
  const inputs = [sourceHash, assetHashes];
  if (diagrams?.size) inputs.push([MERMAID_RENDER_REVISION, Array.from(diagrams, ([index, asset]) => [index, asset.hash])]);
  return digest(JSON.stringify(inputs));
}

async function preparedNotes(app, config, check) {
  const guard = async () => { config.checkPreparation?.(); await check?.(); };
  await guard();
  const renderer = config.mermaidMode === "image" ? localMermaid(app) : null;
  const folder = app.vault.getFolderByPath(config.source);
  if (!folder) throw new Error("The selected source folder does not exist in this vault.");
  const notes = [];
  const folders = new Set();
  const titles = new Map();
  const binaries = new Map();
  const files = sourceMarkdownFiles(folder, config.source);
  for (const file of files.sort((a, b) => a.path.localeCompare(b.path))) {
    await guard();
    for (const path of ancestors(file.path, config.source)) folders.add(path);
    const path = file.path;
    if (!visibleSourcePath(path, config.source)) throw new Error("The source folder hierarchy changed. Reload the review.");
    const title = normalized(file.basename);
    titles.set(title.toLowerCase(), (titles.get(title.toLowerCase()) ?? 0) + 1);
    let problem = title.length > 255 ? new SyncError("A source title exceeds the Confluence maximum: {title}", { title: title.slice(0, 100) }) : null;
    let source;
    try { source = await app.vault.read(file); } catch (error) { problem = error; source = ""; }
    await guard();
    if (file.path !== path) throw new Error("The source folder hierarchy changed. Reload the review.");
    const assets = new Map();
    const diagrams = new Map();
    const references = [];
    const units = markdownLines(source, reference => references.push(reference));
    if (config.mermaidMode === "image") {
      for (const [index, token] of units.entries()) {
        if (token.type !== "fence" || token.info.trim().split(/\s+/)[0].toLowerCase() !== "mermaid") continue;
        await guard();
        try {
          const asset = await renderer.render(token.content.replace(/\n$/, ""));
          await guard();
          token.cfsDiagram = asset;
          diagrams.set(index, asset);
        } catch (error) { if (error.name === "AbortError") throw error; problem = error; }
      }
    }
    for (const reference of references) {
      const target = vaultReference(reference, file, app, config.source);
      if (!target || target.file.extension?.toLowerCase() === "md") continue;
      const assetPath = target.file.path;
      let asset = binaries.get(assetPath);
      if (!asset) {
        if (target.file.stat.size > MAX_ATTACHMENT_BYTES) {
          problem = new SyncError("An attachment exceeds this plugin's 25 MiB limit: {name}", { name: target.file.name });
          continue;
        }
        let data;
        try { data = await app.vault.readBinary(target.file); } catch (error) { problem = error; continue; }
        if (target.file.path !== assetPath || !visibleSourcePath(assetPath, config.source)) {
          throw new Error("The source folder hierarchy changed. Reload the review.");
        }
        if (data.byteLength > MAX_ATTACHMENT_BYTES) {
          problem = new SyncError("An attachment exceeds this plugin's 25 MiB limit: {name}", { name: target.file.name });
          continue;
        }
        const hash = await digest(data);
        const safeName = target.file.name.replace(/[^a-zA-Z0-9_.-]/g, "_").slice(-100);
        asset = { data, hash, file: target.file, name: "cfs-" + hash.slice(0, 24) + "-" + safeName };
        binaries.set(assetPath, asset);
      }
      assets.set(assetPath, asset);
    }
    const sourceHash = await digest(source);
    const assetHashes = Array.from(assets, ([path, asset]) => [path, asset.hash])
      .sort(([left], [right]) => left.localeCompare(right));
    const inputHash = await publicationInputHash(sourceHash, assetHashes, diagrams);
    const dependencies = references.map(reference => vaultReference(reference, file, app, config.source))
      .filter(target => target?.file.extension?.toLowerCase() === "md").map(target => target.file.path);
    notes.push({ file, path, title, original: source, units, assets, diagrams, sourceHash, inputHash, dependencies, problem });
  }
  for (const note of notes) {
    if (!unchangedSourcePaths(note, config.source)) throw new Error("The source folder hierarchy changed. Reload the review.");
    if (titles.get(note.title.toLowerCase()) > 1) {
      note.problem = new SyncError("Duplicate page title in the source folder: {title}", { title: note.title });
    }
  }
  return { notes, folders: Array.from(folders).sort((a, b) => a.split("/").length - b.split("/").length || a.localeCompare(b)) };
}

function resolvedStorage(note, app, client, ids) {
  return toStorage(note.units, reference => {
    const target = vaultReference(reference, note.file, app, client.config.source);
    const label = reference.labelHtml ?? textMarkup(reference.label);
    if (target) {
      const page = ids.get(target.file.path);
      if (page) {
        const url = client.pageUrl(page) + (target.anchor ? "#" + encodeURIComponent(localSlug(target.anchor)) : "");
        return '<a href="' + xml(url) + '">' + label + "</a>";
      }
      const asset = note.assets.get(target.file.path);
      if (asset) {
        const attachment = '<ri:attachment ri:filename="' + asset.name + '" />';
        if (reference.embed && IMAGE_FILE.test(target.file.name)) {
          return '<ac:image ac:alt="' + xml(reference.label) + '">' + attachment + "</ac:image>";
        }
        return '<ac:link>' + attachment + '<ac:link-body>' + label + '</ac:link-body></ac:link>';
      }
    }
    if (/^https?:\/\//i.test(reference.target)) {
      const url = webLink(reference.target, client.config.origin);
      if (url) return '<a href="' + xml(url) + '">' + label + "</a>";
    }
    return label;
  });
}

function confirmParent(kind, remote, expected, parent, title, spaceId) {
  const id = numericId(remote.id);
  if (remote.status !== "current" || String(remote.parentId) !== parent || String(remote.spaceId) !== spaceId ||
      normalized(remote.title) !== title || (expected?.id && id !== expected.id)) {
    throw new SyncError("Confluence {kind} changed position, name or status: {title}", { kind, title });
  }
  return id;
}

function validateVersion(remote, entry) {
  const version = remote.version.number;
  if (version === entry.version) return false;
  if (entry.pending && version === entry.version + 1 && remote.version.message === entry.pending.message) return true;
  throw new SyncError("Confluence page has an independent edit: {title}. Run Preview Confluence changes.", { title: remote.title });
}

function placeholder(entry) {
  return "<p>Confluence Folder Sync pending " + entry.ticket + "</p>";
}

class Publisher {
  constructor(client, app, profile, save) {
    this.client = client;
    this.app = app;
    this.profile = profile;
    this.save = save;
  }

  async inspect(kind, entries, key, title, parent, catalog) {
    if (kind === "page") guardMappedPath(this.profile, key.slice(5));
    const recorded = entries[key] ?? (kind === "folder" ? this.profile.retiredFolders?.[key] : undefined);
    if (recorded?.id) {
      if ((!parent && !(kind === "page" && recorded.renamedFrom)) || !catalog.has(recorded.id)) {
        throw new SyncError("A mapped item is outside the configured folder: {title}", { title });
      }
      const remote = kind === "page" ? await this.client.page(recorded.id) :
        await this.client.get(API + "/folders/" + recorded.id);
      const recovery = kind === "page" && recorded.pending && remote.version.number === recorded.version + 1 &&
        remote.version.message === recorded.pending.message;
      const expectedParent = recovery ? recorded.pending.parent ?? parent : recorded.renamedFrom ? recorded.parent : parent;
      const expectedTitle = recovery ? recorded.pending.title ?? title : recorded.renamedFrom ? recorded.title : title;
      confirmParent(kind, remote, recorded, expectedParent, expectedTitle, this.client.spaceId);
      if (kind === "page") validateVersion(remote, recorded);
      if (kind === "page" && recorded.renamedFrom && title !== remote.title) {
        const matches = await this.client.pageTitles(title);
        if (matches.some(item => String(item.id) !== recorded.id)) {
          throw new SyncError("An existing Confluence item is not linked to this source: {title}", { title });
        }
      }
      return remote;
    }

    const matches = kind === "page" ? await this.client.pageTitles(title) :
      Array.from(catalog.values()).filter(item => parent && String(item.parentId) === parent &&
        normalized(item.title).toLowerCase() === title.toLowerCase());
    if (!matches.length) {
      if (recorded?.creating) throw new SyncError("The previous create result is unknown: {title}", { title });
      return null;
    }
    if (kind === "page" && recorded?.creating && matches.length === 1 && parent) {
      const candidate = await this.client.page(matches[0].id, undefined, true);
      if (candidate.version.number === 1 && candidate.body.storage.value.trim() === placeholder(recorded)) {
        confirmParent(kind, candidate, recorded, parent, title, this.client.spaceId);
        return candidate;
      }
    }
    throw new SyncError("An existing Confluence item is not linked to this source: {title}", { title });
  }

  async plan(tree, catalog) {
    for (const note of tree.notes) if (note.problem) throw note.problem;
    const folders = new Map([[this.client.config.source, this.client.config.folderId]]);
    for (const path of tree.folders) {
      const remote = await this.inspect("folder", this.profile.folders, "dir:" + path,
        normalized(path.split("/").at(-1)), folders.get(parentPath(path)), catalog);
      folders.set(path, remote ? numericId(remote.id) : null);
    }
    for (const note of tree.notes) {
      await this.inspect("page", this.profile.pages, "file:" + note.file.path, note.title,
        folders.get(parentPath(note.file.path)), catalog);
    }
  }

  async claim(kind, entries, key, title, parent, catalog, check) {
    let remote = await this.inspect(kind, entries, key, title, parent, catalog);
    const retired = kind === "folder" ? this.profile.retiredFolders?.[key] : null;
    const restoring = retired && !entries[key];
    const entry = entries[key] ??= retired ? structuredClone(retired) : { ticket: crypto.randomUUID() };
    if (restoring) {
      delete this.profile.retiredFolders[key];
      await this.save();
    }
    if (!remote) {
      await check?.();
      entry.creating = true;
      await this.save();
      let requested = false;
      try {
        await check?.();
        requested = true;
        remote = await this.client.create(kind, title, parent, placeholder(entry));
      } catch (error) {
        if (!requested || (error instanceof ApiError && [400, 401, 403, 404, 413, 429].includes(error.status))) {
          delete entry.creating;
          await this.save();
        }
        throw error;
      }
      confirmParent(kind, remote, entry, parent, title, this.client.spaceId);
    }
    if (!entry.id) {
      entry.id = numericId(remote.id);
      if (kind === "page") {
        entry.version = remote.version.number;
        entry.title = title;
        entry.parent = parent;
      }
      delete entry.creating;
      await this.save();
    }
    catalog.set(entry.id, remote);
    return entry;
  }

  async publish(tree, catalog, control = {}) {
    for (const note of tree.notes) if (note.problem) throw note.problem;
    const folders = new Map([[this.client.config.source, this.client.config.folderId]]);
    const ids = new Map(Object.entries(this.profile.pages)
      .filter(([key, entry]) => key.startsWith("file:" + this.client.config.source + "/") && entry.id && catalog.has(entry.id))
      .map(([key, entry]) => [key.slice(5), entry.id]));
    for (const path of tree.folders) {
      await control.check?.();
      const entry = await this.claim("folder", this.profile.folders, "dir:" + path,
        normalized(path.split("/").at(-1)), folders.get(parentPath(path)), catalog, () => control.check?.());
      folders.set(path, entry.id);
    }
    for (const note of tree.notes) {
      await control.check?.(note);
      const entry = await this.claim("page", this.profile.pages, "file:" + note.file.path, note.title,
        folders.get(parentPath(note.file.path)), catalog, () => control.check?.(note));
      ids.set(note.file.path, entry.id);
    }
    let changed = 0;
    for (const [index, note] of tree.notes.entries()) {
      await control.progress?.(index, tree.notes.length, note.path);
      await control.check?.(note);
      const entry = this.profile.pages["file:" + note.file.path];
      const page = await this.client.page(entry.id);
      await control.check?.(note);
      const parent = folders.get(parentPath(note.file.path));
      const recovery = entry.pending && page.version.number === entry.version + 1 && page.version.message === entry.pending.message;
      confirmParent("page", page, entry, recovery ? entry.pending.parent ?? parent : entry.renamedFrom ? entry.parent : parent,
        recovery ? entry.pending.title ?? note.title : entry.renamedFrom ? entry.title : note.title, this.client.spaceId);
      if (validateVersion(page, entry)) {
        const recoveredInput = entry.pending.preserveMigrated ? entry.pending.inputHash : null;
        entry.inputHash = entry.pending.inputHash;
        entry.formatRevision = entry.pending.formatRevision ?? 0;
        const inventory = attachmentInventory(await this.client.attachments(entry.id));
        const managed = new Set([...publicationAssets(note).map(asset => asset.name), ...Object.keys(entry.uploadIntents ?? {})]);
        const merged = new Map((entry.remoteAttachments ?? []).map(asset => [asset.id, asset]));
        for (const asset of inventory) if (managed.has(asset.title)) merged.set(asset.id, asset);
        entry.remoteAttachments = entry.remoteAttachments ? Array.from(merged.values()) : inventory;
        delete entry.uploadIntents;
        entry.version = page.version.number;
        entry.bodyHash = entry.pending.bodyHash;
        entry.sourceHash = entry.pending.sourceHash;
        entry.title = entry.pending.title ?? note.title;
        entry.parent = entry.pending.parent ?? parent;
        delete entry.pending;
        if (recoveredInput) entry.migratedInputHash = recoveredInput;
        else delete entry.migratedInputHash;
        delete entry.renamedFrom;
        delete entry.requiresReview;
        await this.save();
      }
      const relocation = page.title !== note.title || String(page.parentId) !== parent;
      const preserveMigrated = preservePublishedBody(entry, note);
      if (preservePublishedBody(entry, note) && !relocation && !entry.pending && !entry.uploadIntents) continue;
      const body = preservePublishedBody(entry, note) ? await checkedBody(this.client, page) :
        resolvedStorage(note, this.app, this.client, ids);
      const bodyHash = await digest(body);
      if (bodyHash === entry.bodyHash && !relocation) {
        const unfinished = Boolean(entry.pending || entry.uploadIntents);
        if (unfinished) {
          const files = await this.client.attachments(entry.id);
          if (attachmentsConflict(entry, note, files)) {
            throw new Error("Confluence attachments changed. Review the conflict before publishing.");
          }
          const managed = new Set(Object.keys(entry.uploadIntents ?? {}));
          const inventory = attachmentInventory(files);
          const merged = new Map((entry.remoteAttachments ?? []).map(asset => [asset.id, asset]));
          for (const asset of inventory) if (managed.has(asset.title)) merged.set(asset.id, asset);
          entry.remoteAttachments = entry.remoteAttachments ? Array.from(merged.values()) : inventory;
          delete entry.pending;
          delete entry.uploadIntents;
        }
        if (entry.sourceHash !== note.sourceHash || unfinished) {
          entry.sourceHash = note.sourceHash;
          entry.inputHash = note.inputHash;
          await this.save();
        }
        continue;
      }
      const assets = Array.from(new Map(publicationAssets(note).map(asset => [asset.name, asset])).values());
      const remoteFiles = assets.length || entry.remoteAttachments ? await this.client.attachments(entry.id) : [];
      if (attachmentsConflict(entry, note, remoteFiles)) {
        throw new Error("Confluence attachments changed. Review the conflict before publishing.");
      }
      if (assets.length) {
        const existing = new Map(remoteFiles.map(asset => [asset.title, asset]));
        for (const asset of assets) {
          const found = existing.get(asset.name);
          if (!found) {
            entry.uploadIntents ??= {};
            entry.uploadIntents[asset.name] = { hash: asset.hash, size: asset.data.byteLength };
            await this.save();
            await control.check?.(note);
            await this.client.upload(entry.id, asset);
          }
          else if (found.comment !== asset.hash || found.fileSize !== asset.data.byteLength) {
            throw new SyncError("An attachment name exists with different content: {title}", { title: note.title });
          }
        }
      }
      if (entry.remoteAttachments && attachmentsConflict(entry, note, await this.client.attachments(entry.id))) {
        throw new Error("Confluence attachments changed. Review the conflict before publishing.");
      }
      const message = "Confluence Folder Sync " + entry.ticket + " " + bodyHash.slice(0, 24);
      await control.check?.(note);
      entry.pending = { bodyHash, sourceHash: note.sourceHash, message, title: note.title, parent,
        preserveMigrated, inputHash: note.inputHash, formatRevision: preserveMigrated ? entry.formatRevision ?? 0 : MARKDOWN_FORMAT_REVISION };
      await this.save();
      await control.check?.(note);
      const result = await this.client.update(page, body, message, relocation ? { title: note.title, parent } : undefined);
      if (numericId(result.id) !== entry.id || result.version.number !== page.version.number + 1 ||
          (relocation && (result.title !== note.title || String(result.parentId) !== parent))) {
        throw new Error("Confluence did not confirm the expected update.");
      }
      if (!entry.remoteAttachments || assets.length || Object.keys(entry.uploadIntents ?? {}).length) {
        const inventory = attachmentInventory(await this.client.attachments(entry.id));
        if (!entry.remoteAttachments) {
          entry.remoteAttachments = inventory;
        } else {
          const managed = new Set([...assets.map(asset => asset.name), ...Object.keys(entry.uploadIntents ?? {})]);
          const merged = new Map(entry.remoteAttachments.map(asset => [asset.id, asset]));
          for (const asset of inventory) if (managed.has(asset.title)) merged.set(asset.id, asset);
          entry.remoteAttachments = Array.from(merged.values());
        }
      }
      entry.version = result.version.number;
      entry.bodyHash = bodyHash;
      if (!preserveMigrated) entry.formatRevision = MARKDOWN_FORMAT_REVISION;
      entry.sourceHash = note.sourceHash;
      delete entry.uploadIntents;
      entry.inputHash = note.inputHash;
      entry.title = note.title;
      entry.parent = parent;
      delete entry.pending;
      if (!preserveMigrated) delete entry.migratedInputHash;
      delete entry.renamedFrom;
      delete entry.requiresReview;
      await this.save();
      changed++;
    }
    await control.progress?.(tree.notes.length, tree.notes.length, "");
    return changed;
  }
}


function pageTrails(catalog, root) {
  const trails = new Map();
  for (const [id, item] of catalog) {
    if (item.type !== "page" || item.status !== "current") continue;
    const seen = new Set();
    const trail = [];
    let current = item;
    while (current) {
      const currentId = numericId(current.id);
      if (seen.has(currentId)) throw new Error("Confluence returned a cyclic parent hierarchy.");
      seen.add(currentId);
      trail.unshift(current);
      const parent = String(current.parentId);
      if (parent === root) {
        trails.set(id, trail);
        break;
      }
      current = catalog.get(parent);
    }
  }
  return trails;
}

async function checkedBody(client, item, version) {
  const page = await client.page(item.id, version, true);
  if (String(page.id) !== String(item.id) || String(page.spaceId) !== client.spaceId ||
      page.version.number !== (version ?? item.version.number) ||
      (version === undefined && (String(page.parentId) !== String(item.parentId) || page.status !== "current"))) {
    throw new Error("A page changed during this run. Run the command again.");
  }
  const value = page.body?.storage?.value;
  if (typeof value !== "string") throw new Error("Confluence did not return the page's storage body.");
  return value;
}

function readableComponent(item) {
  let title = normalized(item.title).replace(/[\\/:*?"<>|#^[\]\x00-\x1f]/g, "-").replace(/^[. ]+|[. ]+$/g, "");
  title = Array.from(title).slice(0, 45).join("").trim();
  return (title || "Confluence") + " -- " + numericId(item.id);
}

async function makeVaultFolders(vault, target, inbox) {
  if (!pathIn(target, inbox)) throw new Error("The import path is outside the configured import folder.");
  const parts = target.split("/");
  let folder;
  for (const part of parts) {
    folder = folder ? folder + "/" + part : part;
    if (vault.getFolderByPath(folder)) continue;
    if (vault.getAbstractFileByPath(folder)) throw new SyncError("A file occupies the import folder path: {path}", { path: folder });
    try {
      await vault.createFolder(folder);
    } catch (error) {
      if (!vault.getFolderByPath(folder)) throw error;
    }
  }
}

function attachmentName(entry) {
  const name = normalized(entry.title).replace(/[\\/:*?"<>|#^[\]\x00-\x1f]/g, "-").trim();
  return entry.id + "-v" + entry.version + "-" + (Array.from(name).slice(-100).join("").replace(/[. ]+$/g, "") || "attachment");
}

async function copyRemotePage(vault, client, page, trail, body, destination) {
  const directory = destination + "/" + trail.map(readableComponent).join("/");
  const id = numericId(page.id);
  const version = page.version.number;
  const url = client.pageUrl(id);
  const attachments = await client.attachments(id);
  const inventory = attachmentInventory(attachments);
  const seen = new Set();
  if (inventory.some(asset => asset.size > MAX_ATTACHMENT_BYTES)) {
    throw new SyncError("A Confluence attachment exceeds the 25 MiB limit for {title}.", { title: page.title });
  }
  await makeVaultFolders(vault, directory, client.config.inbox);
  if (attachments.length) await makeVaultFolders(vault, directory + "/Attachments", client.config.inbox);
  const links = new Map();
  for (const attachment of attachments) {
    const entry = attachmentEntry(attachment);
    if (seen.has(entry.title)) throw new Error("Confluence returned duplicate attachment names.");
    seen.add(entry.title);
    const name = attachmentName(entry);
    const path = directory + "/Attachments/" + name;
    const data = await client.downloadAttachment(id, attachment);
    const prior = vault.getFileByPath(path);
    if (!prior) await vault.createBinary(path, data);
    else if (await digest(await vault.readBinary(prior)) !== await digest(data)) {
      throw new SyncError("An existing local attachment has different content: {name}", { name });
    }
    links.set(entry.title, { path: "Attachments/" + encodeURIComponent(name), image: IMAGE_FILE.test(entry.title) });
  }
  const markdown = "# " + markdownText(page.title) + "\n\n[Confluence · version " + version + "](" + url + ")\n\n" +
    fromStorage(body, url, links) + (links.size ? "\n## Confluence attachments\n\n" +
      Array.from(links, ([title, link]) => "- [" + markdownText(title) + "](<" + link.path + ">)").join("\n") + "\n" : "");
  const path = directory + "/v" + version + ".md";
  const existing = vault.getFileByPath(path);
  if (existing && await vault.read(existing) !== markdown) {
    throw new SyncError("An existing local file has different contents: {path}", { path });
  }
  const file = existing ?? await vault.create(path, markdown);
  return { file, inventory };
}

async function remotePages(client, catalog) {
  const trails = pageTrails(catalog, client.config.folderId);
  const pages = await client.currentPages(Array.from(trails.keys()));
  for (const [id, page] of pages) {
    if (String(page.parentId) !== String(trails.get(id).at(-1).parentId)) {
      throw new Error("A page moved during this run. Run the command again.");
    }
  }
  return { trails, pages };
}

async function downloadSnapshot(vault, client, remote, selectedId) {
  const language = client.config.language ?? "en";
  const t = (message, values) => translate(language, message, values);
  const copies = [];
  const selection = selectedId ? [[selectedId, remote.pages.get(selectedId)]] : Array.from(remote.pages);
  if (selection.some(([, page]) => !page)) throw new Error("The selected page is unavailable in this folder.");
  if (!selection.length) throw new Error("The selected folder contains no pages.");
  const date = new Date().toISOString().replace(/[:.]/g, "-");
  const destination = client.config.inbox + "/Snapshots/" + date + " " + crypto.randomUUID().slice(0, 8);
  try {
    for (const [id, page] of selection) {
      const body = await checkedBody(client, page);
      const copy = await copyRemotePage(vault, client, page, remote.trails.get(id), body, destination);
      copies.push(copy.file);
    }
  } catch (error) {
    throw new SyncError("Snapshot stopped after {count} copies. {reason} Check {path} for saved files.",
      { count: copies.length, reason: localizedError(error, language), path: destination });
  }
  const summary = t("{count} current copies saved", { count: copies.length });
  if (copies.length === 1) return { file: copies[0], summary };
  const links = copies.map(file => {
    const route = file.path.slice(destination.length + 1);
    return "- [" + markdownText(parentPath(route).split("/").at(-1)) + "](<" + encodeURI(route).replace(/#/g, "%23") + ">)";
  });
  const file = await vault.create(destination + "/Snapshot index.md",
    "# " + t("Confluence snapshot") + "\n\n" + summary + "\n\n" + links.join("\n") + "\n");
  return { file, summary };
}

async function incoming(app, client, catalog, profile, save, importNew) {
  const language = client.config.language ?? "en";
  const t = (message, values) => translate(language, message, values);
  const { trails, pages } = await remotePages(client, catalog);
  const linked = new Map(Object.entries(profile.pages).filter(([key, entry]) =>
    key.startsWith("file:" + client.config.source + "/") && entry.id).map(([key, entry]) =>
    [entry.id, { ...entry, path: key.slice(5) }]));
  const changes = [];
  let newCount = 0;
  let changedCount = 0;
  let importedCount = 0;
  let baselines = 0;
  const remoteAttachments = new Map();
  if (!importNew) {
    const trackedIds = Array.from(pages.keys()).filter(id => linked.has(id) || profile.imports[id]);
    await mapConcurrent(trackedIds, async id => {
      remoteAttachments.set(id, attachmentInventory(await client.attachments(id)));
    });
  }
  for (const [id, page] of pages) {
    const local = linked.get(id) ?? profile.imports[id];
    const label = "[" + markdownText(page.title) + "](" + client.pageUrl(id) + ")";
    if (!local) {
      newCount++;
      if (importNew) {
        const body = await checkedBody(client, page);
        const copy = await copyRemotePage(app.vault, client, page, trails.get(id), body,
          client.config.inbox + "/Imported pages");
        profile.imports[id] = { path: copy.file.path, version: page.version.number, title: page.title,
          parent: String(page.parentId), remoteAttachments: copy.inventory };
        await save();
        importedCount++;
      }
      changes.push("- " + t("New") + " · " + label);
      continue;
    }
    const version = page.version.number;
    const moved = String(page.parentId) !== local.parent;
    const renamed = page.title !== local.title;
    const inventory = remoteAttachments.get(id);
    let fileChanges = [];
    if (inventory) {
      if (local.remoteAttachments) {
        fileChanges = attachmentDiff(local.remoteAttachments, inventory);
      } else {
        const entry = linked.has(id) ? profile.pages["file:" + local.path] : profile.imports[id];
        entry.remoteAttachments = inventory;
        baselines++;
      }
    }
    if (version === local.version && !moved && !renamed && !fileChanges.length) continue;
    changedCount++;
    if (importNew) continue;
    const details = ["### " + label, "- " + t("Confluence version {before} → {after}", { before: local.version, after: version }),
      "- " + t("Local path: {path}", { path: markdownText(local.path) })];
    const file = app.vault.getFileByPath(local.path);
    const localText = file ? await app.vault.read(file) : null;
    const both = linked.has(id) && localText !== null && local.sourceHash && await digest(localText) !== local.sourceHash;
    if (both) details.push("- " + t("Both the local note and the Confluence page changed."));
    if (moved) details.push("- " + t("The Confluence parent changed."));
    if (renamed) details.push("- " + t("The Confluence title changed."));
    for (const file of fileChanges) {
      const versionLabel = file.before ? "v" + file.before + " → v" + file.version : "v" + file.version;
      details.push("- " + t("Attachment " + file.kind.toLowerCase()) + " · " + markdownText(file.title) + " · " + versionLabel);
    }
    if (version !== local.version) {
      const url = client.pageUrl(id);
      const latest = fromStorage(await checkedBody(client, page), url);
      try {
        details.push(lineChange(fromStorage(await checkedBody(client, page, local.version), url), latest, language));
      } catch (error) {
        if (!(error instanceof ApiError) || ![403, 404].includes(error.status)) throw error;
        details.push(t("The previous version cannot be read."), codeFence(latest, "markdown"));
      }
      if (both) details.push(t("Current local text compared with Confluence:"), lineChange(localText, latest, language));
    }
    changes.push(details.join("\n\n"));
  }

  const missing = new Set([...linked.keys(), ...Object.keys(profile.imports)]);
  for (const id of pages.keys()) missing.delete(id);
  for (const id of missing) changes.push("- " + t("Outside the selected hierarchy or unavailable") + " · " + client.pageUrl(id));
  const summary = t("{new} new · {changed} changed · {imported} imported · {missing} unavailable",
    { new: newCount, changed: changedCount, imported: importedCount, missing: missing.size });
  const title = importNew ? "Confluence import report" : "Confluence change preview";
  const date = new Date().toISOString().replace(/[:.]/g, "-");
  const path = client.config.inbox + "/" + title + " " + date + " " + crypto.randomUUID().slice(0, 8) + ".md";
  const instructions = importNew ?
    "New pages and their attachments are saved under Imported pages." :
    "Review the differences and copy the changes you want to incorporate into the original note.";
  if (baselines) {
    await save();
    changes.unshift(t("Recorded current attachment versions for {count} previously tracked pages.", { count: baselines }));
  }
  await makeVaultFolders(app.vault, client.config.inbox, client.config.inbox);
  const file = await app.vault.create(path, "# " + t(title) + "\n\n" + summary + "\n\n" + t(instructions) +
    (changes.length ? "\n\n" + changes.join("\n\n") : "") + "\n");
  return { file, summary };
}

function reviewHunks(before, after) {
  const diff = diffLines(before, after);
  if (!diff) return [];
  const lines = diff.split("\n");
  const first = /^@@ from line (\d+) @@$/.exec(lines.shift());
  if (!first || lines[0]?.startsWith("Large comparison:")) {
    throw new Error("This comparison is too large for selective application. Use the regular preview.");
  }
  const base = before.trimEnd().split("\n");
  const hunks = [];
  let offset = Number(first[1]) - 1;
  let active;
  for (const line of lines) {
    const marker = line[0];
    if (marker === " ") {
      if (active) hunks.push(active);
      active = null;
      offset++;
      continue;
    }
    if (marker !== "-" && marker !== "+") throw new Error("The comparison could not be split into changes.");
    active ??= { offset, remove: [], insert: [] };
    if (marker === "-") {
      active.remove.push(line.slice(1));
      offset++;
    } else {
      active.insert.push(line.slice(1));
    }
  }
  if (active) hunks.push(active);
  return hunks.map(hunk => ({
    ...hunk,
    before: nearestNonblank(base, hunk.offset - 1, -1),
    after: nearestNonblank(base, hunk.offset + hunk.remove.length, 1),
  }));
}

function nearestNonblank(lines, position, step) {
  for (let at = position; at >= 0 && at < lines.length; at += step) {
    if (lines[at].trim()) return lines[at];
  }
  return null;
}

function textLines(text) {
  return text.replace(/\r\n?/g, "\n").split("\n");
}

function matchHunk(lines, hunk) {
  const locations = [];
  const matchesContext = start => {
    const before = nearestNonblank(lines, start - 1, -1);
    const after = nearestNonblank(lines, start + hunk.remove.length, 1);
    return before === hunk.before && after === hunk.after;
  };
  for (let start = 0; start <= lines.length - hunk.remove.length; start++) {
    if (hunk.remove.every((line, index) => line === lines[start + index]) && matchesContext(start)) {
      locations.push(start);
    }
  }
  if (hunk.remove.length) return locations.length === 1 ? locations[0] : null;
  // Empty lines between the same two anchors are equivalent insertion locations.
  // Distinct occurrences of the anchors are ambiguous.
  if (!locations.length ||
      locations.some((at, index) => index && at !== locations[index - 1] + 1)) return null;
  return locations[0];
}

function mergeSelected(original, chunks) {
  if (/\r(?!\n)/.test(original) || (original.includes("\r\n") && /(^|[^\r])\n/.test(original))) {
    throw new Error("This note has mixed line endings. Apply the changes manually.");
  }
  const lines = textLines(original);
  const sorted = chunks.slice().sort((left, right) => right.at - left.at);
  let boundary = lines.length + 1;
  for (const chunk of sorted) {
    if (chunk.at === null || chunk.at >= boundary || chunk.at + chunk.remove.length > boundary ||
        !chunk.remove.every((line, index) => lines[chunk.at + index] === line)) {
      throw new Error("The selected changes overlap or no longer match the note.");
    }
    lines.splice(chunk.at, chunk.remove.length, ...chunk.insert);
    boundary = chunk.at;
  }
  return lines.join(original.includes("\r\n") ? "\r\n" : "\n");
}

function mappedSource(profile, id, source) {
  const matches = Object.entries(profile.pages).filter(([key, entry]) =>
    key.startsWith("file:") && entry.id === id && key.slice(5).startsWith(source + "/"));
  if (matches.length !== 1) throw new Error("This page is not linked to one published note in the active source folder.");
  const [[key, entry]] = matches;
  guardMappedPath(profile, key.slice(5));
  return { path: key.slice(5), entry };
}

async function prepareLocalReview(app, client, profile, page) {
  const id = numericId(page.id);
  const { path, entry } = mappedSource(profile, id, client.config.source);
  if (entry.pending || entry.creating || !entry.bodyHash) {
    throw new Error("The link has an unfinished publish. Resolve it before reviewing edits.");
  }
  const file = app.vault.getFileByPath(path);
  if (!file || file.extension !== "md") throw new SyncError("The linked local Markdown file is unavailable: {path}", { path });
  const original = await app.vault.read(file);
  const latest = await checkedBody(client, page);
  const prior = page.version.number === entry.version ? latest : await checkedBody(client, page, entry.version);
  const url = client.pageUrl(id);
  const hunks = reviewHunks(fromStorage(prior, url), fromStorage(latest, url));
  return { id, path, original, baseVersion: entry.version, version: page.version.number,
    bodyHash: await digest(latest), origin: client.config.origin, folderId: client.config.folderId,
    hunks: hunks.map(hunk => ({ ...hunk, at: matchHunk(textLines(original), hunk) })) };
}

function editorMatches(app, path, original) {
  return app.workspace.getLeavesOfType("markdown").every(({ view }) =>
    view.file?.path !== path || !view.editor ||
      view.editor.getValue().replace(/\r\n/g, "\n") === original.replace(/\r\n/g, "\n"));
}

async function applyLocalReview(app, client, profile, page, review, selection, recordBackup) {
  if (client.config.origin !== review.origin || client.config.folderId !== review.folderId ||
      String(page.id) !== review.id || page.version.number !== review.version) {
    throw new Error("The Confluence page or destination changed. Review the latest version again.");
  }
  const { path, entry } = mappedSource(profile, review.id, client.config.source);
  if (path !== review.path || entry.version !== review.baseVersion || entry.pending ||
      await digest(await checkedBody(client, page)) !== review.bodyHash) {
    throw new Error("The Confluence page or its link changed. Review the latest version again.");
  }
  const indexes = Array.from(new Set(selection));
  if (!indexes.length || indexes.some(index => !Number.isInteger(index) || !review.hunks[index])) {
    throw new Error("Select at least one valid change.");
  }
  const changed = mergeSelected(review.original, indexes.map(index => review.hunks[index]));
  if (changed === review.original) throw new Error("The selected changes would not modify the note.");
  const file = app.vault.getFileByPath(path);
  if (!file || await app.vault.read(file) !== review.original || !editorMatches(app, path, review.original)) {
    throw new Error("The local note changed after review. Review it again.");
  }

  const { backup } = await saveNoteBackup(app, client.config, path, review.original, changed, recordBackup);

  // Recheck after creating the backup and let Vault.process guard against a newer local edit.
  const latest = await client.page(review.id);
  if (String(latest.id) !== review.id || String(latest.spaceId) !== client.spaceId ||
      latest.version.number !== review.version || String(latest.parentId) !== String(page.parentId) ||
      latest.title !== page.title || latest.status !== "current") {
    throw new Error("The Confluence page changed while preparing the backup. No local change was applied.");
  }
  await app.vault.process(file, current => {
    if (current !== review.original || file.path !== path || !editorMatches(app, path, current)) {
      throw new Error("The local note changed while applying the selection. No local change was applied.");
    }
    return changed;
  });
  return { count: indexes.length, backup };
}

function publicationTarget(config) {
  return JSON.stringify([config.origin, config.folderId, config.source]);
}

function attachmentsConflict(entry, note, files) {
  if (!entry.remoteAttachments) return false;
  const desired = new Map(publicationAssets(note).map(asset => [asset.name, asset]));
  const raw = new Map(files.map(file => [file.title, file]));
  return attachmentDiff(entry.remoteAttachments, attachmentInventory(files)).some(change => {
    const asset = desired.get(change.title);
    const intent = entry.uploadIntents?.[change.title];
    const file = raw.get(change.title);
    // A known content-addressed upload may have succeeded before a prior request
    // was interrupted. Existing/deleted/edited remote versions still conflict.
    const hash = intent?.hash ?? asset?.hash;
    const size = intent?.size ?? asset?.data.byteLength;
    return change.kind !== "Added" || !hash || change.version !== 1 ||
      file?.comment !== hash || file?.fileSize !== size;
  });
}

function selectionTree(tree, paths) {
  const selected = new Set(paths);
  const notes = tree.notes.filter(note => selected.has(note.path));
  const folders = new Set(notes.flatMap(note => ancestors(note.path, tree.source)));
  return { ...tree, notes, folders: tree.folders.filter(path => folders.has(path)) };
}

async function publicationReview(app, client, profile, tree, catalog) {
  client = client instanceof ReviewReads ? client : new ReviewReads(client);
  await client.preloadPages(tree.notes.map(note => profile.pages["file:" + note.path]?.id)
    .filter(id => id && catalog.has(id)));
  const config = client.config;
  const publisher = new Publisher(client, app, profile, async () => {});
  const folders = new Map([[config.source, { id: config.folderId }]]);
  const ids = new Map(Object.entries(profile.pages)
    .filter(([key, entry]) => key.startsWith("file:" + config.source + "/") && entry.id && catalog.has(entry.id))
    .map(([key, entry]) => [key.slice(5), entry.id]));
  for (const path of tree.folders) {
    const parent = folders.get(parentPath(path));
    try {
      if (parent?.error) throw parent.error;
      const remote = await publisher.inspect("folder", profile.folders, "dir:" + path,
        normalized(path.split("/").at(-1)), parent?.id ?? null, catalog);
      folders.set(path, { id: remote?.id ?? null });
    } catch (error) {
      folders.set(path, { error });
    }
  }
  const rows = await mapConcurrent(tree.notes, async note => {
    await client.check();
    const entry = profile.pages["file:" + note.path];
    const parent = folders.get(parentPath(note.path));
    const row = { path: note.path, inputHash: note.inputHash, title: note.title, id: entry?.id ?? null,
      renamedFrom: entry?.renamedFrom ?? null,
      dependencies: Array.from(new Set(note.dependencies.filter(path => path !== note.path && !ids.has(path)))) };
    try {
      if (note.problem) throw note.problem;
      if (!editorMatches(app, note.path, note.original)) throw new Error("Save the open editor before publication.");
      if (parent?.error) throw parent.error;
      const page = await publisher.inspect("page", profile.pages, "file:" + note.path,
        note.title, parent?.id ?? null, catalog);
      row.version = page?.version.number ?? null;
      row.parent = page ? String(page.parentId) : null;
      if (page && entry.remoteAttachments) {
        const files = await client.attachments(page.id);
        row.inventoryHash = await digest(JSON.stringify(attachmentInventory(files)));
        if (attachmentsConflict(entry, note, files)) {
          throw new Error("Confluence attachments changed. Review the conflict before publishing.");
        }
      }
      row.outputHash = await digest(resolvedStorage(note, app, client, ids));
      row.formatReviewRequired = Boolean(page && entry.bodyHash && (entry.formatRevision ?? 0) < MARKDOWN_FORMAT_REVISION &&
        entry.sourceHash === note.sourceHash && !preservePublishedBody(entry, note));
      if (row.formatReviewRequired) row.reason = translate(config.language,
        "Review this attachment change manually after the Markdown upgrade.");
      row.status = !page ? "New" : entry.creating || entry.pending ||
        page.title !== note.title || String(page.parentId) !== parent?.id ? "Changed" :
        preservePublishedBody(entry, note) ||
        row.outputHash === entry.bodyHash ? "Unchanged" : "Changed";
    } catch (error) {
      if (error.name === "AbortError") throw error;
      row.status = "Conflict";
      row.reason = localizedError(error, config.language);
    }
    return row;
  });
  for (const row of rows) row.fingerprint = await digest(JSON.stringify(row));
  return { target: publicationTarget(config), rows, source: config.source,
    destination: new URL(config.origin).hostname + " / " + config.folderId };
}

function checkedSelection(review, current, paths) {
  if (review.target !== current.target) throw new Error("The publication destination changed. Refresh the review.");
  const selected = new Set(paths);
  if (!selected.size) throw new Error("Select at least one eligible note.");
  const ready = new Map(current.rows.map(row => [row.path, row]));
  const previous = new Map(review.rows.map(row => [row.path, row]));
  for (const path of selected) {
    const row = ready.get(path);
    const prior = previous.get(path);
    if (!prior || !row || !["New", "Changed"].includes(row.status) || row.fingerprint !== prior.fingerprint) {
      throw new Error("A selected note or page changed. Refresh the publication review.");
    }
    if (row.dependencies.some(dependency => !selected.has(dependency))) {
      throw new Error("Also select the unpublished notes referenced by your selection.");
    }
  }
  return selected;
}

async function checkPublicationInput(app, note, source) {
  const changed = () => { throw new Error("A selected note or page changed. Refresh the publication review."); };
  if (!unchangedSourcePaths(note, source)) changed();
  const inputs = [note.file, ...Array.from(note.assets.values(), asset => asset.file)];
  const stamp = file => JSON.stringify([file.stat?.ctime, file.stat?.mtime, file.stat?.size]);
  const revisions = inputs.map(stamp);
  const text = await app.vault.read(note.file);
  const sourceHash = await digest(text);
  if (!unchangedSourcePaths(note, source) || sourceHash !== note.sourceHash || !editorMatches(app, note.path, note.original)) changed();
  for (const [path, asset] of note.assets) {
    if (asset.file.path !== path || !visibleSourcePath(path, source)) changed();
    const data = await app.vault.readBinary(asset.file);
    if (data.byteLength > MAX_ATTACHMENT_BYTES) changed();
    const hash = await digest(data);
    if (!unchangedSourcePaths(note, source) || hash !== asset.hash) changed();
  }
  for (const asset of note.diagrams?.values() ?? []) {
    if (await digest(asset.data) !== asset.hash) changed();
  }
  const finalHash = await digest(await app.vault.read(note.file));
  if (!unchangedSourcePaths(note, source) || finalHash !== note.sourceHash ||
      !editorMatches(app, note.path, note.original) || inputs.some((file, index) => stamp(file) !== revisions[index])) changed();
}

async function publishSelection(app, client, profile, save, review, paths, control = {}) {
  const previousCheck = client.check;
  client.check = async () => { await previousCheck?.(); await control.check?.(); };
  try {
    await client.check();
    return await publishReviewedSelection(app, client, profile, save, review, paths, control);
  } finally {
    client.check = previousCheck;
  }
}

async function publishReviewedSelection(app, client, profile, save, review, paths, control) {
  if (!client.config.allowPublish) throw new Error("Enable publishing in the plugin settings first.");
  const tree = await preparedNotes(app, client.config, () => client.check?.());
  tree.source = client.config.source;
  const catalog = await client.catalog();
  const current = await publicationReview(app, client, profile, tree, catalog);
  const selected = checkedSelection(review, current, paths);
  const subset = selectionTree(tree, selected);
  // Re-read after remote preflight. A modal can stay open while local files change.
  for (const note of subset.notes) {
    await checkPublicationInput(app, note, client.config.source);
  }
  const publisher = new Publisher(client, app, profile, save);
  await publisher.plan(subset, catalog);
  return publisher.publish(subset, catalog, {
    ...control,
    check: async note => {
      await control.check?.(note);
      for (const selectedNote of note ? [note] : subset.notes) {
        await checkPublicationInput(app, selectedNote, client.config.source);
      }
    },
  });
}

class PublicationModal extends Modal {
  constructor(plugin, review) {
    super(plugin.app);
    this.plugin = plugin;
    this.review = review;
    this.selection = new Set();
    this.t = (message, values) => plugin.t(message, values);
  }

  onOpen() {
    this.opened = true;
    this.contentEl.addClass("cfs-publication");
    this.render();
  }

  onClose() {
    this.opened = false;
    this.cancelled = true;
    this.contentEl.empty();
  }

  render() {
    const { contentEl, t, review } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: t("Review publication") });
    contentEl.createEl("p", { text: review.source + " → " + review.destination });
    const counts = ["New", "Changed", "Unchanged", "Conflict"].map(status =>
      t(status) + " " + review.rows.filter(row => row.status === status).length);
    contentEl.createEl("p", { text: counts.join(" · "), attr: { role: "status", "aria-live": "polite" } });
    if (this.status) contentEl.createEl("p", { text: this.status, attr: { role: "status" } });
    if (!this.plugin.data.settings.allowPublish) contentEl.createEl("p", { text: t("Enable publishing in the plugin settings first.") });
    const controls = new Setting(contentEl);
    controls.addButton(button => button.setButtonText(t("Select eligible notes")).setDisabled(this.busy)
      .onClick(() => {
        this.selection = new Set(review.rows.filter(row => ["New", "Changed"].includes(row.status)).map(row => row.path));
        this.render();
      }));
    controls.addButton(button => button.setButtonText(t("Clear selection")).setDisabled(this.busy)
      .onClick(() => { this.selection.clear(); this.render(); }));
    controls.addButton(button => button.setButtonText(t("Refresh review")).setDisabled(this.busy).onClick(() => this.refresh()));
    if (this.busy) controls.addButton(button => button.setButtonText(t("Cancel"))
      .onClick(() => { this.cancelled = true; this.status = t("Cancelling after the current request…"); this.render(); }));
    new Setting(contentEl).setName(t("Filter notes")).addText(input => input.setValue(this.filter ?? "")
      .setPlaceholder(t("Title or folder")).setDisabled(this.busy).onChange(value => {
        this.filter = value;
        this.renderRows();
      }));
    this.rowsEl = contentEl.createDiv({ cls: "cfs-publication-rows" });
    this.renderRows();
    new Setting(contentEl).setName(t("Selected notes: {count}", { count: this.selection.size }))
      .addButton(button => {
        this.publishButton = button;
        button.setButtonText(t("Publish selected")).setCta()
          .setDisabled(this.busy || !this.selection.size || !this.plugin.data.settings.allowPublish)
          .onClick(() => this.publish());
      });
  }

  renderRows() {
    const { rowsEl, t } = this;
    rowsEl.empty();
    const query = normalized(this.filter ?? "").trim().toLowerCase();
    for (const row of this.review.rows.filter(item => normalized(item.path).toLowerCase().includes(query))) {
      const description = row.reason ?? (row.renamedFrom ? t("Linked page moved from {path}", { path: row.renamedFrom }) : row.dependencies.length ?
        t("Also required: {paths}", { paths: row.dependencies.join(", ") }) : row.id ? "Confluence " + row.id + " · v" + row.version : "");
      new Setting(rowsEl).setName(t(row.status) + " · " + row.path).setDesc(description)
        .addToggle(toggle => toggle.setValue(this.selection.has(row.path))
          .setDisabled(this.busy || !["New", "Changed"].includes(row.status)).onChange(enabled => {
            if (enabled) this.selection.add(row.path);
            else this.selection.delete(row.path);
            this.render();
          }));
    }
  }

  async refresh() {
    this.busy = true;
    this.render();
    try {
      this.review = await this.plugin.preparePublication();
      this.selection.clear();
      this.status = "";
    } catch (error) {
      this.status = localizedError(error, this.plugin.language);
    } finally {
      this.busy = false;
      if (this.opened) this.render();
    }
  }

  async publish() {
    if (this.busy || !this.opened) return;
    this.busy = true;
    this.cancelled = false;
    const paths = Array.from(this.selection);
    this.render();
    try {
      if (!await this.plugin.confirm(this.t("Publish selected"),
        this.t("Publish {count} selected notes to {destination}?", { count: paths.length, destination: this.review.destination }),
        this.t("Publish")) || !this.opened) return;
      const updated = await this.plugin.operation("Publish selected", ({ client, profile, save }) =>
        publishSelection(this.app, client, profile, save, this.review, paths, {
          check: () => {
            if (this.cancelled || this.plugin.unloaded) {
              const error = new Error("The operation was cancelled. Completed changes are preserved.");
              error.name = "AbortError";
              throw error;
            }
            if (!this.plugin.data.settings.allowPublish) throw new Error("Enable publishing in the plugin settings first.");
            if (publicationTarget(validatedConfig(this.plugin.data.settings)) !== this.review.target) {
              throw new Error("The publication destination changed. Refresh the review.");
            }
          },
          progress: (done, total, path) => {
            this.status = this.t("Publishing {done}/{total}: {path}", { done, total, path });
            if (this.opened) this.render();
          },
        }));
      this.status = this.t("Published {count} selected notes.", { count: updated });
      this.review = await this.plugin.preparePublication();
      this.selection.clear();
    } catch (error) {
      this.status = localizedError(error, this.plugin.language);
    } finally {
      this.busy = false;
      if (this.opened) this.render();
    }
  }
}

async function prepareConflict(app, client, profile, page) {
  const { path, entry } = mappedSource(profile, numericId(page.id), client.config.source);
  if (entry.pending || entry.creating || !entry.bodyHash) {
    throw new Error("The link has an unfinished publish. Resolve it before reviewing edits.");
  }
  if (page.title !== entry.title || String(page.parentId) !== entry.parent) {
    throw new Error("Resolve page moves or title changes before resolving text.");
  }
  const file = app.vault.getFileByPath(path);
  if (!file) throw new SyncError("The linked local Markdown file is unavailable: {path}", { path });
  const original = await app.vault.read(file);
  const latest = await checkedBody(client, page);
  const prior = await checkedBody(client, page, entry.version);
  const url = client.pageUrl(page.id);
  return { id: String(page.id), path, original, local: original, base: fromStorage(prior, url),
    remote: fromStorage(latest, url), version: page.version.number, baseVersion: entry.version,
    title: page.title, parent: String(page.parentId), bodyHash: await digest(latest),
    inventory: attachmentInventory(await client.attachments(page.id)),
    target: publicationTarget(client.config) };
}

async function resolveConflict(app, client, profile, save, review, text, recordBackup) {
  if (review.target !== publicationTarget(client.config) || typeof text !== "string") {
    throw new Error("The Confluence page or destination changed. Review the latest version again.");
  }
  const { path, entry } = mappedSource(profile, review.id, client.config.source);
  if (path !== review.path || entry.version !== review.baseVersion || entry.pending || entry.creating) {
    throw new Error("The Confluence page or its link changed. Review the latest version again.");
  }
  const file = app.vault.getFileByPath(path);
  if (!file || await app.vault.read(file) !== review.original || !editorMatches(app, path, review.original)) {
    throw new Error("The local note changed after review. Review it again.");
  }
  const checkRemote = async () => {
    const page = await client.page(review.id, undefined, true);
    if (String(page.id) !== review.id || page.status !== "current" || String(page.spaceId) !== client.spaceId || page.title !== review.title ||
        String(page.parentId) !== review.parent || page.version.number !== review.version ||
        await digest(page.body?.storage?.value ?? "") !== review.bodyHash ||
        JSON.stringify(attachmentInventory(await client.attachments(review.id))) !== JSON.stringify(review.inventory)) {
      throw new Error("The Confluence page changed. Review the conflict again.");
    }
  };
  await checkRemote();
  const { backup } = await saveNoteBackup(app, client.config, path, review.original, text, recordBackup);
  await checkRemote();
  await app.vault.process(file, current => {
    if (current !== review.original || file.path !== path || !editorMatches(app, path, current)) {
      throw new Error("The local note changed while applying the selection. No local change was applied.");
    }
    return text;
  });
  const priorEntry = structuredClone(entry);
  entry.version = review.version;
  entry.bodyHash = review.bodyHash;
  entry.sourceHash = await digest(review.remote);
  entry.remoteAttachments = review.inventory;
  entry.requiresReview = true;
  delete entry.migratedInputHash;
  delete entry.inputHash;
  try {
    if (text === review.remote) {
      const tree = await preparedNotes(app, client.config, () => client.check?.());
      const note = tree.notes.find(item => item.path === path);
      if (!note || note.sourceHash !== await digest(text) || file.path !== path || !editorMatches(app, path, text)) {
        throw new Error("The local note changed after review. Review it again.");
      }
      entry.migratedInputHash = note.inputHash;
      entry.sourceHash = note.sourceHash;
    }
    await save();
  } catch (error) {
    for (const key of Object.keys(entry)) delete entry[key];
    Object.assign(entry, priorEntry);
    throw error;
  }
  return { backup, path, afterHash: await digest(text) };
}

class ConflictModal extends Modal {
  constructor(plugin, review) {
    super(plugin.app);
    this.plugin = plugin;
    this.review = review;
    this.text = review.original;
    this.t = (message, values) => plugin.t(message, values);
  }

  onOpen() {
    this.opened = true;
    this.modalEl.classList.add("cfs-conflict-modal");
    this.contentEl.addClass("cfs-conflict");
    this.render();
  }

  onClose() {
    this.opened = false;
    this.modalEl.classList.remove("cfs-conflict-modal");
    this.contentEl.empty();
  }

  render() {
    const { contentEl, t, review } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: t("Resolve text conflict") });
    contentEl.createEl("p", { text: review.path + " · Confluence v" + review.baseVersion + " → v" + review.version });
    contentEl.createEl("p", { text: t("Review converted text. Attachments stay in Confluence. Publishing the resolution is a separate action.") });
    const columns = contentEl.createDiv({ cls: "cfs-conflict-columns" });
    for (const [label, text] of [["Previous baseline", review.base], ["Current local note", review.local], ["Current Confluence page", review.remote]]) {
      const column = columns.createDiv();
      column.createEl("h3", { text: t(label) });
      column.createEl("pre", { text, attr: { tabindex: "0", "aria-label": t(label) } });
    }
    new Setting(contentEl).setName(t("Resolution text"))
      .addButton(button => button.setButtonText(t("Use local text")).setDisabled(this.busy)
        .onClick(() => { this.text = review.local; this.render(); }))
      .addButton(button => button.setButtonText(t("Use Confluence text")).setDisabled(this.busy)
        .onClick(() => { this.text = review.remote; this.render(); }));
    const editor = contentEl.createEl("textarea", { cls: "cfs-resolution", attr: { "aria-label": t("Resolution text") } });
    editor.value = this.text;
    editor.disabled = Boolean(this.busy);
    editor.addEventListener("input", () => { this.text = editor.value; });
    if (this.status) contentEl.createEl("p", { text: this.status, attr: { role: "status" } });
    new Setting(contentEl).addButton(button => button.setButtonText(t("Save resolution locally")).setCta()
      .setDisabled(this.busy).onClick(() => this.apply()));
  }

  async apply() {
    if (this.busy) return;
    this.busy = true;
    this.render();
    try {
      if (!await this.plugin.confirm(this.t("Save resolution locally"),
        this.t("Back up {path}, save the reviewed text, and accept Confluence v{version} as the new baseline?",
          { path: this.review.path, version: this.review.version }), this.t("Apply changes")) || !this.opened) return;
      const result = await this.plugin.operation("Resolve text conflict", ({ client, profile, save }) =>
        resolveConflict(this.app, client, profile, save, this.review, this.text, receipt => this.plugin.recordBackup(receipt)));
      this.status = this.t("Resolution saved. Review publication to upload your chosen text.");
      this.close();
      new Notice(this.status);
      return result;
    } catch (error) {
      this.status = localizedError(error, this.plugin.language);
    } finally {
      this.busy = false;
      if (this.opened) this.render();
    }
  }
}

function rekeySource(profile, oldPath, newPath) {
  const conflict = profile.renameConflicts?.filter(item => pathIn(oldPath, item.to))
    .sort((a, b) => b.to.length - a.to.length)[0];
  const exactConflict = conflict && conflict.to === oldPath;
  if (exactConflict && newPath === conflict.from) {
    profile.renameConflicts = profile.renameConflicts.filter(item => item !== conflict);
    return 0;
  }
  if (conflict) {
    oldPath = conflict.from + oldPath.slice(conflict.to.length);
    if (pathIn(newPath, conflict.to)) newPath = conflict.from + newPath.slice(conflict.to.length);
  }
  const moves = Object.entries(profile.pages).filter(([key]) => key.startsWith("file:") &&
    pathIn(key.slice(5), oldPath)).map(([key, entry]) => ({
      key, entry, next: "file:" + newPath + key.slice(5 + oldPath.length),
    }));
  const moving = new Set(moves.map(item => item.key));
  for (const item of moves) {
    if (profile.pages[item.next] && !moving.has(item.next)) {
      const error = new Error("A moved note already has another page mapping. Resolve its link first.");
      error.code = "RENAME_COLLISION";
      error.from = oldPath;
      throw error;
    }
  }
  for (const item of moves) delete profile.pages[item.key];
  for (const item of moves) {
    item.entry.renamedFrom ??= item.key.slice(5);
    profile.pages[item.next] = item.entry;
  }
  if (exactConflict) profile.renameConflicts = profile.renameConflicts.filter(item => item !== conflict);
  for (const item of profile.renameConflicts ?? []) {
    if (pathIn(item.from, oldPath)) item.from = newPath + item.from.slice(oldPath.length);
    if (pathIn(item.to, oldPath)) item.to = newPath + item.to.slice(oldPath.length);
  }
  // Folder titles cannot be changed through the v2 Folder API. Rebuild only the
  // selected destination branches, reparent pages, and preserve old folders.
  for (const key of Object.keys(profile.folders)) {
    if (key.startsWith("dir:") && pathIn(key.slice(4), oldPath)) {
      profile.retiredFolders ??= {};
      profile.retiredFolders[key] = profile.folders[key];
      delete profile.folders[key];
    }
  }
  return moves.length;
}

function guardMappedPath(profile, path) {
  if (profile.renameConflicts?.some(item => pathIn(path, item.from) || pathIn(path, item.to))) {
    throw new Error("A local rename has a conflicting page mapping. Undo the move or choose a new path.");
  }
}

async function saveNoteBackup(app, config, path, original, after, record = async () => {}) {
  if (!path.startsWith(config.source + "/") || vaultPath(path) !== path) {
    throw new Error("The linked note is outside the configured source folder.");
  }
  const stamp = new Date().toISOString().replace(/[:.]/g, "-") + " " + crypto.randomUUID().slice(0, 8);
  const backup = config.inbox + "/Backups/" + stamp + "/" + path.slice(config.source.length + 1);
  await makeVaultFolders(app.vault, parentPath(backup), config.inbox);
  await app.vault.create(backup, original);
  const receipt = { id: crypto.randomUUID(), time: new Date().toISOString(), path, backup,
    backupHash: await digest(original), afterHash: await digest(after), target: publicationTarget(config) };
  await record(receipt);
  return receipt;
}

async function restoreNoteBackup(app, config, receipt, record) {
  if (receipt.target !== publicationTarget(config) || vaultPath(receipt.path) !== receipt.path ||
      !receipt.path.startsWith(config.source + "/") || vaultPath(receipt.backup) !== receipt.backup ||
      !receipt.backup.startsWith(config.inbox + "/Backups/")) {
    throw new Error("This backup belongs to another source or destination.");
  }
  const file = app.vault.getFileByPath(receipt.path);
  const backup = app.vault.getFileByPath(receipt.backup);
  if (!file || !backup || file.extension !== "md") throw new Error("The note or backup is unavailable.");
  const original = await app.vault.read(file);
  const text = await app.vault.read(backup);
  if (await digest(text) !== receipt.backupHash) throw new Error("The backup contents changed. Open it for manual review.");
  if (await digest(original) !== receipt.afterHash || !editorMatches(app, file.path, original)) {
    throw new Error("The note changed after this backup. Open the backup and review it manually.");
  }
  const recovery = await saveNoteBackup(app, config, file.path, original, text, record);
  await app.vault.process(file, current => {
    if (file.path !== receipt.path || current !== original || !editorMatches(app, receipt.path, current)) {
      throw new Error("The local note changed while applying the selection. No local change was applied.");
    }
    return text;
  });
  return recovery;
}

class HistoryModal extends Modal {
  constructor(plugin) {
    super(plugin.app);
    this.plugin = plugin;
    this.t = (message, values) => plugin.t(message, values);
  }

  onOpen() {
    this.contentEl.addClass("cfs-history");
    this.render();
  }

  render() {
    const { contentEl, plugin, t } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: t("Activity and backups") });
    if (this.status) contentEl.createEl("p", { text: this.status, attr: { role: "status" } });
    contentEl.createEl("h3", { text: t("Recent operations") });
    for (const item of plugin.data.history.slice().reverse().slice(0, 30)) {
      const result = item.status === "Running" && !plugin.running ? "Interrupted" : item.status;
      new Setting(contentEl).setName(t(item.action) + " · " + t(result))
        .setDesc(item.time + (item.error ? " · " + item.error : item.count !== undefined ? " · " + item.count : ""));
    }
    if (!plugin.data.history.length) contentEl.createEl("p", { text: t("No recorded operations yet.") });
    contentEl.createEl("h3", { text: t("Local note backups") });
    for (const receipt of plugin.data.backups.slice().reverse().slice(0, 30)) {
      new Setting(contentEl).setName(receipt.path).setDesc(receipt.time)
        .addButton(button => button.setButtonText(t("Open backup")).onClick(async () => {
          const file = this.app.vault.getFileByPath(receipt.backup);
          if (file) await this.app.workspace.getLeaf("tab").openFile(file);
          this.close();
        }))
        .addButton(button => button.setButtonText(t("Restore backup")).setDisabled(this.busy || plugin.running)
          .onClick(() => this.restore(receipt)));
    }
    if (!plugin.data.backups.length) contentEl.createEl("p", { text: t("No recorded backups yet.") });
  }

  async restore(receipt) {
    this.busy = true;
    this.render();
    try {
      if (!await this.plugin.confirm(this.t("Restore backup"),
        this.t("Restore {path}? The current note will be backed up first.", { path: receipt.path }),
        this.t("Restore backup"))) return;
      await this.plugin.exclusive(() => this.plugin.recordOperation("Restore backup", () => {
        const config = validatedConfig(this.plugin.data.settings);
        guardMappedPath(this.plugin.data.profiles[publicationTarget(config)] ?? {}, receipt.path);
        return restoreNoteBackup(this.app, config, receipt, item => this.plugin.recordBackup(item));
      }));
      this.status = this.t("Backup restored locally.");
    } catch (error) {
      this.status = localizedError(error, this.plugin.language);
    } finally {
      this.busy = false;
      this.render();
    }
  }

  onClose() {
    this.contentEl.empty();
  }
}

function automaticCandidates(review, profile, tree) {
  const notes = new Map(tree.notes.map(note => [note.path, note]));
  return review.rows.filter(row => {
    const entry = profile.pages["file:" + row.path];
    const note = notes.get(row.path);
    const baseline = entry?.inputHash ?? entry?.migratedInputHash;
    return row.status === "Changed" && !row.formatReviewRequired && row.id && entry && note && !entry.renamedFrom &&
      entry.bodyHash && entry.sourceHash && !entry.requiresReview && !entry.pending && !entry.creating && !row.dependencies.length &&
      (baseline ? baseline !== note.inputHash : entry.sourceHash !== note.sourceHash);
  }).map(row => row.path);
}

class AutomaticSync {
  constructor(plugin, timers = globalThis) {
    this.plugin = plugin;
    this.timers = timers;
  }

  configure() {
    if (this.disposed) return;
    this.clearTimers();
    if (!this.plugin.data.settings.autoCheck) return;
    const minutes = [5, 15, 60].includes(this.plugin.data.settings.autoMinutes) ? this.plugin.data.settings.autoMinutes : 5;
    this.interval = this.timers.setInterval(() => this.schedule(), minutes * 60_000);
    this.schedule();
  }

  changed(file, oldPath) {
    const source = this.plugin.data.settings.source + "/";
    if (file.path.startsWith(source) || oldPath?.startsWith(source)) this.schedule();
  }

  schedule(delay = 5000) {
    if (this.disposed || !this.plugin.data.settings.autoCheck || this.timer) return;
    this.timer = this.timers.setTimeout(() => {
      this.timer = null;
      void this.run();
    }, delay);
  }

  async run() {
    const plugin = this.plugin;
    if (this.disposed || !plugin.data.settings.autoCheck) return;
    if (this.busy || plugin.running || Date.now() - (this.lastAttempt ?? 0) < 60_000) {
      this.schedule(60_000);
      return;
    }
    this.busy = true;
    this.lastAttempt = Date.now();
    try {
      const result = await plugin.operation("Automatic check", async ({ client, profile, save }) => {
        const tree = await preparedNotes(plugin.app, client.config, () => client.check?.());
        const catalog = await client.catalog();
        const reads = new ReviewReads(client);
        const review = await publicationReview(plugin.app, reads, profile, tree, catalog);
        const remote = await remotePages(reads, catalog);
        const linked = new Map(Object.values(profile.pages).map(entry => [entry.id, entry]));
        const remoteChanges = new Set();
        const tracked = [];
        for (const [id, page] of remote.pages) {
          const entry = linked.get(id) ?? profile.imports[id];
          if (!entry || entry.version !== page.version.number || entry.title !== page.title ||
              entry?.parent !== String(page.parentId)) remoteChanges.add(id);
          if (entry?.remoteAttachments) tracked.push([id, entry]);
        }
        await mapConcurrent(tracked, async ([id, entry]) => {
          const inventory = attachmentInventory(await reads.attachments(id));
          if (attachmentDiff(entry.remoteAttachments, inventory).length) remoteChanges.add(id);
        });
        let published = 0;
        if (plugin.data.settings.autoPublish && plugin.data.settings.allowPublish) {
          const paths = automaticCandidates(review, profile, tree);
          if (paths.length) {
            published = await plugin.recordOperation("Automatic publish", () =>
              publishSelection(plugin.app, client, profile, save, review, paths, {
                check: () => {
                  if (this.disposed || !plugin.data.settings.autoCheck || !plugin.data.settings.autoPublish ||
                      !plugin.data.settings.allowPublish || publicationTarget(validatedConfig(plugin.data.settings)) !== review.target) {
                    const error = new Error("The operation was cancelled. Completed changes are preserved.");
                    error.name = "AbortError";
                    throw error;
                  }
                },
              }));
          }
        }
        return { review, remoteChanges: remoteChanges.size, published };
      });
      const counts = Object.fromEntries(["New", "Changed", "Conflict"].map(status =>
        [status, result.review.rows.filter(row => row.status === status).length]));
      const message = plugin.t("Automatic review: {new} new, {changed} changed, {conflicts} conflicts, {remote} remote changes, {published} published.",
        { new: counts.New, changed: counts.Changed, conflicts: counts.Conflict, remote: result.remoteChanges, published: result.published });
      plugin.automaticStatus = new Date().toLocaleTimeString() + " · " + message;
      if ((counts.New || counts.Changed || counts.Conflict || result.remoteChanges || result.published) && message !== this.lastMessage) {
        new Notice(message, 10000);
      }
      this.lastMessage = message;
    } catch (error) {
      const message = localizedError(error, plugin.language);
      plugin.automaticStatus = message;
      if (message !== this.lastMessage) new Notice(message, 12000);
      this.lastMessage = message;
    } finally {
      this.busy = false;
    }
  }

  clearTimers() {
    if (this.timer) this.timers.clearTimeout(this.timer);
    if (this.interval) this.timers.clearInterval(this.interval);
    this.timer = null;
    this.interval = null;
  }

  dispose() {
    this.disposed = true;
    this.clearTimers();
  }
}

// Management changes local metadata only. Publication remains a separate review.
function mappingProfileKey(key) {
  try {
    const parts = JSON.parse(key);
    if (Array.isArray(parts) && parts.length === 3 && parts.every(value => typeof value === "string")) return parts;
  } catch { /* Ignore legacy or invalid profile keys. */ }
  return null;
}

function mappingInterrupted(entry) {
  return Boolean(entry?.creating || entry?.pending || Object.keys(entry?.uploadIntents ?? {}).length);
}

async function mappingInventory(app, client, profile) {
  const tree = await preparedNotes(app, client.config, () => client.check?.());
  const catalog = await client.catalog();
  const visible = pageTrails(catalog, client.config.folderId);
  const paths = new Set(tree.notes.map(note => note.path));
  for (const key of Object.keys(profile.pages)) {
    if (key.startsWith("file:" + client.config.source + "/")) paths.add(key.slice(5));
  }
  const ids = Object.values(profile.pages).map(entry => entry.id).filter(Boolean);
  const rows = Array.from(paths).sort().map(path => {
    const entry = profile.pages["file:" + path];
    const local = tree.notes.some(note => note.path === path);
    const conflict = profile.renameConflicts?.some(item => pathIn(path, item.from) || pathIn(path, item.to)) ||
      (entry?.id && ids.filter(id => id === entry.id).length > 1);
    const status = conflict ? "Mapping conflict" : !local ? "Local file missing" : !entry ? "Unlinked" :
      mappingInterrupted(entry) ? "Interrupted publication" : !visible.has(entry.id) ? "Unavailable" : "Linked";
    return { path, id: entry?.id ?? "", status };
  });
  return { rows, pages: Array.from(visible, ([id, trail]) => ({ id,
    label: trail.map(item => item.title).join(" / ") })).sort((a, b) => a.label.localeCompare(b.label)) };
}

function mappingOwners(profiles, config, id) {
  return Object.entries(profiles).flatMap(([key, profile]) => {
    const parts = mappingProfileKey(key);
    if (!parts || parts[0] !== config.origin) return [];
    return Object.entries(profile.pages ?? {}).filter(([, entry]) => entry.id === id)
      .map(([path]) => ({ target: key, path }));
  });
}

async function prepareMappingChange(app, client, data, request) {
  const config = client.config;
  const target = publicationTarget(config);
  const profile = data.profiles[target];
  if (!profile) throw new Error("Refresh the connection management screen.");
  const state = await digest(JSON.stringify(data.profiles));
  const next = structuredClone(data.profiles);
  const destination = next[target];
  const tree = await preparedNotes(app, config, () => client.check?.());
  const catalog = await client.catalog();
  const trails = pageTrails(catalog, config.folderId);
  const locals = [];
  const remotes = [];
  const changes = [];
  const noteAt = path => {
    const note = tree.notes.find(item => item.path === path);
    if (!note || note.problem || !editorMatches(app, path, note.original)) {
      throw new Error("Save a valid note inside the active source folder before reconnecting.");
    }
    guardMappedPath(profile, path);
    locals.push({ path, sourceHash: note.sourceHash, inputHash: note.inputHash });
    return note;
  };
  const pageAt = async id => {
    id = numericId(id);
    const listed = catalog.get(id);
    if (!trails.has(id) || !listed) throw new Error("The selected page is unavailable in this folder.");
    const page = await client.page(id, undefined, true);
    confirmParent("page", page, { id }, String(listed.parentId), normalized(listed.title), client.spaceId);
    const body = page.body?.storage?.value;
    if (typeof body !== "string") throw new Error("Confluence did not return the page's storage body.");
    const files = await client.attachments(id);
    const bodyHash = await digest(body);
    remotes.push({ id, title: page.title, parent: String(page.parentId), version: page.version.number,
      message: page.version.message ?? "", bodyHash, inventory: attachmentInventory(files) });
    return { page, body, bodyHash, files, inventory: attachmentInventory(files) };
  };
  const folderAt = async path => {
    let parent = config.folderId;
    for (const folder of ancestors(path, config.source)) {
      const key = "dir:" + folder;
      const title = normalized(folder.split("/").at(-1));
      const entry = destination.folders[key];
      const matches = Array.from(catalog.values()).filter(item => item.type === "folder" &&
        item.status === "current" && String(item.parentId) === parent && normalized(item.title) === title);
      if (matches.length !== 1 || (entry && entry.id !== String(matches[0].id))) {
        throw new Error("The matching Confluence folder hierarchy is missing or ambiguous.");
      }
      const remote = await client.get(API + "/folders/" + numericId(matches[0].id));
      confirmParent("folder", remote, entry, parent, title, client.spaceId);
      remotes.push({ folder: String(remote.id), parent, title });
      destination.folders[key] ??= { id: String(remote.id), ticket: "reconnected-" + remote.id };
      parent = String(remote.id);
    }
    return parent;
  };
  if (request.action === "reconnect") {
    const note = noteAt(request.path);
    const key = "file:" + note.path;
    if (destination.pages[key]) throw new Error("The destination note already has a mapping.");
    const oldKey = request.from ? "file:" + request.from : null;
    const prior = oldKey ? profile.pages[oldKey] : null;
    if (oldKey && (!pathIn(request.from, config.source) || !prior || app.vault.getFileByPath(request.from))) {
      throw new Error("Choose a missing local mapping as the previous link.");
    }
    const remote = await pageAt(request.id);
    if (mappingOwners(data.profiles, config, request.id).some(owner => owner.target !== target || owner.path !== oldKey)) {
      throw new Error("The page is already linked to another note or source profile.");
    }
    if (prior) {
      if (prior.id !== request.id || mappingInterrupted(prior) || prior.renamedFrom || !prior.bodyHash ||
          prior.version !== remote.page.version.number || prior.bodyHash !== remote.bodyHash ||
          prior.title !== remote.page.title || prior.parent !== String(remote.page.parentId) ||
          prior.sourceHash !== note.sourceHash || (prior.inputHash ?? prior.migratedInputHash) !== note.inputHash || !prior.remoteAttachments ||
          attachmentDiff(prior.remoteAttachments, remote.inventory).length) {
        throw new Error("The previous link or its contents changed. Resolve the differences before reconnecting.");
      }
      delete destination.pages[oldKey];
      destination.pages[key] = { ...structuredClone(prior), renamedFrom: request.from, requiresReview: true };
      changes.push(request.from + " → " + note.path + " · " + request.id);
    } else {
      const parent = await folderAt(note.path);
      const ids = new Map(Object.entries(profile.pages).filter(([, entry]) => entry.id)
        .map(([path, entry]) => [path.slice(5), entry.id]));
      ids.set(note.path, request.id);
      if (note.dependencies.some(path => !ids.has(path)) || remote.page.title !== note.title ||
          String(remote.page.parentId) !== parent || resolvedStorage(note, app, client, ids) !== remote.body ||
          Array.from(note.assets.values()).some(asset => !remote.files.some(file => file.title === asset.name &&
            file.comment === asset.hash && file.fileSize === asset.data.byteLength))) {
        throw new Error("The note and existing page do not match. Download a copy and reconcile them first.");
      }
      destination.pages[key] = { id: request.id, ticket: "reconnected-" + request.id,
        version: remote.page.version.number, title: remote.page.title, parent,
        bodyHash: remote.bodyHash, sourceHash: note.sourceHash, inputHash: note.inputHash,
        remoteAttachments: remote.inventory, requiresReview: true };
      changes.push(note.path + " ↔ " + request.id);
    }
  } else if (request.action === "recover") {
    const note = noteAt(request.path);
    const key = "file:" + note.path;
    const entry = destination.pages[key];
    if (!mappingInterrupted(entry)) throw new Error("This mapping has no interrupted publication.");
    if (!entry.id && entry.creating) {
      const parent = await folderAt(note.path);
      const candidates = await client.pageTitles(note.title);
      if (candidates.length !== 1) throw new Error("The create result cannot be proved. Keep the recovery marker and inspect Confluence.");
      const remote = await pageAt(String(candidates[0].id));
      if (remote.page.version.number !== 1 || remote.body.trim() !== placeholder(entry) ||
          remote.page.title !== note.title || String(remote.page.parentId) !== parent ||
          mappingOwners(data.profiles, config, String(remote.page.id)).length) {
        throw new Error("The create result cannot be proved. Keep the recovery marker and inspect Confluence.");
      }
      Object.assign(entry, { id: String(remote.page.id), version: 1, title: note.title, parent, requiresReview: true });
      delete entry.creating;
      changes.push(note.path + " ↔ " + entry.id);
    } else {
      const owners = mappingOwners(data.profiles, config, entry.id);
      if (owners.length !== 1 || owners[0].target !== target || owners[0].path !== key) {
        throw new Error("The page is already linked to another note or source profile.");
      }
      const remote = await pageAt(entry.id);
      const pending = entry.pending;
      const completed = pending && remote.page.version.number === entry.version + 1 &&
        remote.page.version.message === pending.message && remote.bodyHash === pending.bodyHash;
      const unchanged = remote.page.version.number === entry.version && remote.bodyHash === entry.bodyHash;
      const title = completed ? pending.title ?? entry.title : entry.title;
      const parent = completed ? pending.parent ?? entry.parent : entry.parent;
      if ((!completed && !unchanged) || remote.page.title !== title || String(remote.page.parentId) !== parent ||
          !entry.remoteAttachments || attachmentsConflict(entry, note, remote.files)) {
        throw new Error("The interrupted result changed independently. Review the conflict before recovery.");
      }
      if (!completed) throw new Error("The page update is not confirmed. Resume it through Review publication; no marker was cleared.");
      entry.version = remote.page.version.number;
      entry.bodyHash = pending.bodyHash;
      entry.sourceHash = pending.sourceHash;
      entry.inputHash = pending.inputHash;
      entry.formatRevision = pending.formatRevision ?? 0;
      entry.title = title;
      entry.parent = parent;
      entry.remoteAttachments = remote.inventory;
      if (pending.preserveMigrated) entry.migratedInputHash = pending.inputHash;
      else delete entry.migratedInputHash;
      delete entry.pending;
      delete entry.uploadIntents;
      delete entry.renamedFrom;
      entry.requiresReview = true;
      changes.push(note.path + " · v" + entry.version);
    }
  } else if (request.action === "migrate") {
    const parts = mappingProfileKey(request.fromTarget);
    const origin = data.profiles[request.fromTarget];
    if (!parts || parts[0] !== config.origin || parts[1] !== config.folderId || parts[2] === config.source ||
        !origin || !Object.keys(origin.pages ?? {}).length || Object.keys(profile.pages).length ||
        Object.keys(profile.folders).length || Object.keys(profile.retiredFolders ?? {}).length ||
        profile.renameConflicts?.length || origin.renameConflicts?.length || Object.keys(origin.retiredFolders ?? {}).length) {
      throw new Error("Choose an established source profile for this destination and an empty current mapping.");
    }
    const oldSource = vaultPath(parts[2]);
    // This action moves ownership; the previous profile remains a read-only tombstone.
    for (const [key, entry] of Object.entries(origin.pages)) {
      if (!key.startsWith("file:" + oldSource + "/") || mappingInterrupted(entry) || entry.renamedFrom) {
        throw new Error("Resolve interrupted publications and moves before migrating the source root.");
      }
      const path = config.source + key.slice(5 + oldSource.length);
      const note = noteAt(path);
      const remote = await pageAt(entry.id);
      const previousInputs = await publicationInputHash(note.sourceHash,
        Array.from(note.assets, ([path, asset]) => [oldSource + path.slice(config.source.length), asset.hash])
          .sort(([left], [right]) => left.localeCompare(right)), note.diagrams);
      if (entry.sourceHash !== note.sourceHash || (entry.migratedInputHash ?? entry.inputHash) !== previousInputs ||
          entry.bodyHash !== remote.bodyHash ||
          entry.version !== remote.page.version.number || entry.title !== remote.page.title ||
          entry.parent !== String(remote.page.parentId) || !entry.remoteAttachments ||
          attachmentDiff(entry.remoteAttachments, remote.inventory).length ||
          mappingOwners(data.profiles, config, entry.id).length !== 1) {
        throw new Error("A migration baseline differs. Resolve it in the previous configuration first.");
      }
      destination.pages["file:" + path] = { ...structuredClone(entry), inputHash: note.inputHash, requiresReview: true };
      if (entry.migratedInputHash) destination.pages["file:" + path].migratedInputHash = note.inputHash;
      changes.push(key.slice(5) + " → " + path + " · " + entry.id);
    }
    for (const [key, entry] of Object.entries(origin.folders ?? {})) {
      if (!key.startsWith("dir:" + oldSource + "/") || !entry.id || entry.creating) {
        throw new Error("Resolve interrupted publications and moves before migrating the source root.");
      }
      const remote = catalog.get(entry.id);
      if (!remote || remote.type !== "folder" || remote.status !== "current") {
        throw new Error("The matching Confluence folder hierarchy is missing or ambiguous.");
      }
      destination.folders["dir:" + config.source + key.slice(4 + oldSource.length)] = structuredClone(entry);
    }
    // Verify every mapped branch against its expected relative hierarchy.
    for (const key of Object.keys(destination.folders)) await folderAt(key.slice(4) + "/check.md");
    for (const note of locals) await folderAt(note.path);
    next[request.fromTarget] = { pages: {}, folders: {}, imports: structuredClone(origin.imports ?? {}), movedTo: target };
    delete destination.movedTo;
  } else throw new Error("Choose a connection management action.");
  // Remote reads can take time: re-read all local inputs after the last await.
  const latest = await preparedNotes(app, config, () => client.check?.());
  for (const local of locals) {
    const note = latest.notes.find(item => item.path === local.path);
    if (!note || note.inputHash !== local.inputHash || !editorMatches(app, local.path, note.original)) {
      throw new Error("The local note changed after review. Review it again.");
    }
  }
  if (state !== await digest(JSON.stringify(data.profiles))) throw new Error("The mapping changed. Preview it again.");
  const plan = { target, request: structuredClone(request), state, locals, remotes, changes, next };
  plan.fingerprint = await digest(JSON.stringify(plan));
  return plan;
}

async function applyMappingChange(app, client, data, save, review, check = () => {}) {
  check();
  const fresh = await prepareMappingChange(app, client, data, review.request);
  if (fresh.fingerprint !== review.fingerprint) throw new Error("The mapping changed. Preview it again.");
  check();
  const profiles = data.profiles;
  const backups = data.mappingBackups ?? [];
  const receipt = { id: crypto.randomUUID(), time: new Date().toISOString(), target: review.target,
    action: review.request.action, changes: review.changes, profiles: structuredClone(profiles) };
  data.profiles = fresh.next;
  data.mappingBackups = [...backups, receipt].slice(-10);
  data.settings.autoPublish = false;
  try { await save(); } catch (error) {
    data.profiles = profiles;
    data.mappingBackups = backups;
    throw error;
  }
  return review.changes.length;
}

class MappingModal extends Modal {
  constructor(plugin) {
    super(plugin.app);
    this.plugin = plugin;
    this.t = (message, values) => plugin.t(message, values);
    this.action = "reconnect";
    this.status = this.t("Load connections to inspect local mapping state.");
  }

  onOpen() { this.opened = true; this.contentEl.addClass("cfs-management"); this.render(); }
  onClose() { this.opened = false; this.contentEl.empty(); }

  render() {
    const { contentEl, t } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: t("Connections and recovery") });
    contentEl.createEl("p", { text: t("Management updates local links only. Documents stay unchanged. Automatic publication is disabled after applying a change.") });
    contentEl.createEl("p", { text: this.status, attr: { role: "status", "aria-live": "polite" } });
    new Setting(contentEl).addButton(button => button.setButtonText(t("Load connections")).setDisabled(this.busy)
      .onClick(() => this.load()));
    if (!this.inventory) return;
    const select = (name, field, options) => {
      new Setting(contentEl).setName(t(name)).addDropdown(dropdown => {
        dropdown.selectEl.setAttribute("aria-label", t(name));
        dropdown.addOption("", t("Choose an item"));
        for (const [value, label] of options) dropdown.addOption(value, label);
        dropdown.setValue(this[field] ?? "").setDisabled(this.busy).onChange(value => {
          this[field] = value; this.review = null; this.render();
        });
      });
    };
    new Setting(contentEl).setName(t("Filter connections")).addText(input => input.setValue(this.filter ?? "")
      .setDisabled(this.busy).onChange(value => { this.filter = value; this.renderRows(); }));
    this.rowsEl = contentEl.createDiv({ cls: "cfs-management-rows" });
    this.renderRows();
    select("Management action", "action", [["reconnect", t("Reconnect existing page")],
      ["recover", t("Recover completed publication")], ["migrate", t("Migrate source root")]]);
    if (this.action === "migrate") {
      select("Previous source profile", "fromTarget", this.sources);
    } else {
      select("Local note", "path", this.inventory.rows.filter(row => this.action === "recover" ?
        row.status === "Interrupted publication" : row.status === "Unlinked").map(row => [row.path, row.path]));
      if (this.action === "reconnect") {
        select("Previous missing link (optional)", "from", this.inventory.rows.filter(row => row.status === "Local file missing")
          .map(row => [row.path, row.path + " · " + row.id]));
        select("Existing Confluence page", "id", this.inventory.pages.map(page => [page.id, page.label + " · " + page.id]));
      }
    }
    new Setting(contentEl).addButton(button => button.setButtonText(t("Preview mapping change"))
      .setDisabled(this.busy || !this.action).onClick(() => this.preview()));
    if (this.review) {
      contentEl.createEl("h3", { text: t("Mapping change preview") });
      contentEl.createEl("p", { text: this.review.target });
      const list = contentEl.createEl("ul");
      for (const change of this.review.changes) list.createEl("li", { text: change });
      new Setting(contentEl).addButton(button => button.setButtonText(t("Apply mapping change")).setCta()
        .setDisabled(this.busy).onClick(() => this.apply()));
    }
  }

  renderRows() {
    this.rowsEl.empty();
    const term = normalized(this.filter ?? "").toLowerCase();
    for (const row of this.inventory.rows.filter(item => (item.path + " " + item.id + " " + this.t(item.status)).toLowerCase().includes(term))) {
      this.rowsEl.createEl("p", { text: this.t(row.status) + " · " + row.path + (row.id ? " · " + row.id : "") });
    }
  }

  async perform(task) {
    if (this.busy) return;
    this.busy = true; this.render();
    try { await task(); } catch (error) { this.review = null; this.status = localizedError(error, this.plugin.language); }
    finally { this.busy = false; if (this.opened) this.render(); }
  }

  load() {
    return this.perform(async () => {
      this.review = null;
      await this.plugin.withConnection(async ({ client, profile }) => {
        this.inventory = await mappingInventory(this.app, client, profile);
        this.sources = Object.entries(this.plugin.data.profiles).filter(([key, entry]) => {
          const parts = mappingProfileKey(key);
          return parts && parts[0] === client.config.origin && parts[1] === client.config.folderId &&
            parts[2] !== client.config.source && Object.keys(entry.pages ?? {}).length;
        }).map(([key]) => [key, mappingProfileKey(key)[2]]);
      }, { management: true });
      this.status = this.t("{count} local mapping items loaded.", { count: this.inventory.rows.length });
    });
  }

  preview() {
    const request = this.action === "migrate" ? { action: this.action, fromTarget: this.fromTarget } :
      this.action === "recover" ? { action: this.action, path: this.path } :
        { action: this.action, path: this.path, from: this.from || null, id: this.id };
    return this.perform(async () => {
      this.review = null;
      this.review = await this.plugin.withConnection(({ client }) => prepareMappingChange(this.app, client, this.plugin.data, request), { management: true });
      this.status = this.t("Review the proposed links before applying. A local metadata backup will be retained.");
    });
  }

  apply() {
    const review = this.review;
    return this.perform(async () => {
      if (!review || !await this.plugin.confirm(this.t("Apply mapping change"),
        this.t("Apply {count} reviewed link changes? Documents stay unchanged; automatic publication will be disabled.",
          { count: review.changes.length }), this.t("Apply mapping change")) || !this.opened) return;
      await this.plugin.operation("Manage connections", ({ client, config, save }) =>
        applyMappingChange(this.app, client, this.plugin.data, save, review, () => {
          if (!this.opened || this.plugin.unloaded || publicationTarget(validatedConfig(this.plugin.data.settings)) !== publicationTarget(config)) {
            throw new Error("The mapping changed. Preview it again.");
          }
        }), { management: true });
      this.plugin.automatic?.configure();
      this.review = null; this.inventory = null;
      this.status = this.t("Connection metadata saved. Reload connections, then review publication manually.");
    });
  }
}

const SETUP_KEYS = ["folderUrl", "email", "secretId", "source", "inbox"];
const SETUP_PHASES = ["target", "account", "folders", "readAccess"];
const SETUP_ISSUES = {
  TARGET: ["Check the Confluence folder URL.", "Copy an HTTPS folder URL from the Confluence sidebar, including /folder/ and its numeric ID."],
  ACCOUNT: ["Check the account and token selection.", "Enter the Atlassian email that issued the token and select a secret stored in Obsidian."],
  SECRET: ["The selected secret is unavailable.", "Create or select a token in Obsidian SecretStorage. Token values are never stored in connection settings."],
  FOLDERS: ["Check the local folder paths.", "Use separate visible relative folders for source and imports. Hidden, absolute and overlapping paths are not allowed."],
  SOURCE: ["The source folder is unavailable.", "Choose an existing source folder in this vault. The wizard does not create or modify source notes."],
  INBOX: ["A file occupies the import folder path.", "Choose an import folder whose path is not occupied by a file. Missing folders are created only when importing."],
  AUTH: ["Authentication was rejected.", "Check the Atlassian email, token expiration and selected secret, then test again."],
  FORBIDDEN: ["Read access was denied.", "Check the token's Confluence read scopes and the account's folder restrictions with your administrator."],
  NOT_FOUND: ["The folder could not be found or accessed.", "Check the folder URL and account access. A hidden or inaccessible folder may also appear missing."],
  LIMITED: ["Confluence is temporarily limiting requests.", "Wait for the server's retry period, then test again."],
  SERVICE: ["Confluence is temporarily unavailable.", "Try again later. No remote writes were attempted."],
  REQUEST: ["The connection could not be verified.", "Check your network or proxy and try again. Share only the redacted diagnostics if the issue continues."],
  STALE: ["The setup check is no longer current.", "Test again after changing fields or the selected secret. Checks expire after five minutes."],
  SETTINGS_CHANGED: ["The saved settings changed while this wizard was open.", "Close and reopen setup to use the latest settings. No connection settings were replaced."],
  BUSY: ["Another sync operation is running.", "Wait for it to finish before testing or saving this connection."],
  SAVE: ["The connection settings could not be saved.", "The previous settings were restored. Check local write access and try again."],
  SAVE_UNCERTAIN: ["The connection settings could not be saved or restored on disk.", "Previous settings remain in memory. Check local write access and inspect settings before continuing."],
  CANCELLED: ["Setup was cancelled.", "Reopen setup when you are ready. No remaining connection checks will be started."],
};

class SetupIssue extends Error {
  constructor(code) { super(code); this.code = code; }
}

function setupDraft(settings) {
  return Object.fromEntries(SETUP_KEYS.map(key => [key, typeof settings[key] === "string" ? settings[key] : ""]));
}

function setupFingerprint(settings) { return JSON.stringify(setupDraft(settings)); }

function setupIssueCode(error) {
  if (error instanceof SetupIssue && Object.hasOwn(SETUP_ISSUES, error.code)) return error.code;
  if (error?.name === "AbortError") return "CANCELLED";
  if (error instanceof RetryWaitError) return "LIMITED";
  if (error instanceof ApiError) {
    return ({ 401: "AUTH", 403: "FORBIDDEN", 404: "NOT_FOUND", 429: "LIMITED", 503: "SERVICE" })[error.status] ?? "REQUEST";
  }
  if (error?.message === "A Confluence command is already running in this vault.") return "BUSY";
  return "REQUEST";
}

function setupTarget(draft) {
  try { return confluenceTarget(draft.folderUrl); } catch { throw new SetupIssue("TARGET"); }
}

function setupAccount(app, draft) {
  let account;
  try { account = atlassianAccount(draft.email, draft.secretId); } catch { throw new SetupIssue("ACCOUNT"); }
  try {
    if (!app.secretStorage.getSecret(account.secretId)) throw new Error();
  } catch { throw new SetupIssue("SECRET"); }
  return account;
}

function setupFolders(app, draft) {
  let paths;
  try { paths = configuredFolders(draft.source, draft.inbox); } catch { throw new SetupIssue("FOLDERS"); }
  const source = app.vault.getFolderByPath(paths.source);
  if (!source) throw new SetupIssue("SOURCE");
  let noteCount;
  try { noteCount = sourceMarkdownFiles(source, paths.source).length; } catch { throw new SetupIssue("SOURCE"); }
  let prefix = "";
  for (const part of paths.inbox.split("/")) {
    prefix = prefix ? prefix + "/" + part : part;
    if (app.vault.getAbstractFileByPath(prefix) && !app.vault.getFolderByPath(prefix)) throw new SetupIssue("INBOX");
  }
  return { ...paths, noteCount, inboxMissing: !app.vault.getFolderByPath(paths.inbox) };
}

function inspectSetup(app, draft) {
  const checks = [];
  const values = {};
  for (const [id, inspect] of [["target", () => setupTarget(draft)], ["account", () => setupAccount(app, draft)],
    ["folders", () => setupFolders(app, draft)]]) {
    try { Object.assign(values, inspect()); checks.push({ id, status: "pass" }); }
    catch (error) { checks.push({ id, status: "fail", code: setupIssueCode(error) }); }
  }
  return { ok: checks.every(check => check.status === "pass"), checks, values };
}

async function verifySetup(app, draft, createClient, check = async () => {}) {
  const snapshot = setupDraft(draft);
  await check();
  const local = inspectSetup(app, snapshot);
  const result = { ok: false, checks: local.checks, fingerprint: setupFingerprint(snapshot), checkedAt: Date.now() };
  if (!local.ok) return result;
  try {
    const config = { ...snapshot, ...local.values, allowPublish: false, autoCheck: false, autoPublish: false };
    const token = app.secretStorage.getSecret(config.secretId);
    if (!token) throw new SetupIssue("SECRET");
    const tokenHash = await digest(token);
    await check();
    const client = createClient(config, token, check);
    await client.connect();
    await check();
    const descendants = await client.get(API + "/folders/" + config.folderId + "/descendants", { limit: 1, depth: 1 });
    if (!Array.isArray(descendants.results)) throw new Error();
    await check();
    const current = inspectSetup(app, snapshot);
    if (!current.ok) return { ...result, checks: current.checks };
    if (await digest(app.secretStorage.getSecret(config.secretId) ?? "") !== tokenHash) throw new SetupIssue("STALE");
    await check();
    return { ...result, ok: true, checks: [...current.checks, { id: "readAccess", status: "pass" }],
      tokenHash, noteCount: current.values.noteCount, checkedAt: Date.now() };
  } catch (error) {
    if (error?.name === "AbortError" || error instanceof SetupIssue && error.code === "SETTINGS_CHANGED") throw error;
    const status = error instanceof ApiError && Number.isInteger(error.status) && error.status >= 100 && error.status <= 599 ? error.status : undefined;
    return { ...result, checks: [...result.checks, { id: "readAccess", status: "fail", code: setupIssueCode(error), httpStatus: status }] };
  }
}

function setupDiagnostics(plugin, result, issue) {
  const version = value => typeof value === "string" && /^\d+\.\d+\.\d+(?:[-+][a-zA-Z0-9.-]+)?$/.test(value) ? value : "unknown";
  const report = { schema: 1, plugin: "confluence-folder-sync", pluginVersion: version(plugin.manifest?.version),
    obsidianVersion: version(apiVersion), outcome: result?.ok === true ? "pass" : "not-verified", checks: [] };
  for (const item of result?.checks ?? []) {
    if (!SETUP_PHASES.includes(item.id)) continue;
    const entry = { check: item.id, outcome: item.status === "pass" ? "pass" : "fail" };
    if (Object.hasOwn(SETUP_ISSUES, item.code)) entry.code = item.code;
    if (Number.isInteger(item.httpStatus) && item.httpStatus >= 100 && item.httpStatus <= 599) entry.httpStatus = item.httpStatus;
    report.checks.push(entry);
  }
  if (Object.hasOwn(SETUP_ISSUES, issue)) report.issue = issue;
  return report;
}

function requireSetupProof(draft, verified) {
  if (!verified?.ok || verified.fingerprint !== setupFingerprint(draft) || !Number.isFinite(verified.checkedAt) ||
      Date.now() - verified.checkedAt < 0 || Date.now() - verified.checkedAt > 300000) throw new SetupIssue("STALE");
}

async function commitSetup(plugin, draft, verified, baseline, check = async () => {}) {
  if (plugin.setupSaving) throw new SetupIssue("BUSY");
  plugin.setupSaving = true;
  try {
    await check();
    if (JSON.stringify(plugin.data.settings) !== baseline) throw new SetupIssue("SETTINGS_CHANGED");
    requireSetupProof(draft, verified);
    const local = inspectSetup(plugin.app, draft);
    if (!local.ok) throw new SetupIssue(local.checks.find(item => item.status === "fail").code);
    const token = plugin.app.secretStorage.getSecret(draft.secretId) ?? "";
    if (await digest(token) !== verified.tokenHash) throw new SetupIssue("STALE");
    await check();
    if (JSON.stringify(plugin.data.settings) !== baseline) throw new SetupIssue("SETTINGS_CHANGED");
    requireSetupProof(draft, verified);
    const current = inspectSetup(plugin.app, draft);
    if (!current.ok) throw new SetupIssue(current.checks.find(item => item.status === "fail").code);
    if (plugin.app.secretStorage.getSecret(draft.secretId) !== token) throw new SetupIssue("STALE");
    const previous = structuredClone(plugin.data.settings);
    plugin.data.settings = { ...previous, ...setupDraft({ ...draft, ...current.values }), folderUrl: draft.folderUrl.trim(),
      allowPublish: false, autoCheck: false, autoPublish: false };
    const savedFingerprint = JSON.stringify(plugin.data.settings);
    try {
      await plugin.persist();
      await check(savedFingerprint);
      requireSetupProof(draft, verified);
      if (JSON.stringify(plugin.data.settings) !== savedFingerprint) throw new SetupIssue("SETTINGS_CHANGED");
      const final = inspectSetup(plugin.app, draft);
      if (!final.ok) throw new SetupIssue(final.checks.find(item => item.status === "fail").code);
      if (plugin.app.secretStorage.getSecret(draft.secretId) !== token) throw new SetupIssue("STALE");
    } catch (error) {
      plugin.data.settings = previous;
      try { await plugin.persist(); } catch { throw new SetupIssue("SAVE_UNCERTAIN"); }
      if (error instanceof SetupIssue || error?.name === "AbortError") throw error;
      throw new SetupIssue("SAVE");
    }
    plugin.automatic?.configure();
  } finally { plugin.setupSaving = false; }
}

class SetupModal extends Modal {
  constructor(plugin, onSaved = () => {}) {
    super(plugin.app);
    this.plugin = plugin;
    this.t = (message, values) => plugin.t(message, values);
    this.baseline = JSON.stringify(plugin.data.settings);
    this.draft = setupDraft(plugin.data.settings);
    this.step = 0;
    this.onSaved = onSaved;
  }

  onOpen() { this.opened = true; this.contentEl.addClass("cfs-setup"); this.render(); }
  onClose() { this.opened = false; this.contentEl.empty(); }

  change(key, value) {
    this.draft[key] = value;
    this.verified = null;
    this.issue = null;
    this.report = null;
    this.reportContainer?.remove();
    this.issueContainer?.remove();
  }

  guard(fingerprint, settings = this.baseline) {
    if (!this.opened || this.plugin.unloaded) { const error = new Error(); error.name = "AbortError"; throw error; }
    if (setupFingerprint(this.draft) !== fingerprint) throw new SetupIssue("STALE");
    if (JSON.stringify(this.plugin.data.settings) !== settings) throw new SetupIssue("SETTINGS_CHANGED");
  }

  render() {
    const { contentEl, t, plugin } = this;
    contentEl.empty();
    this.reportContainer = null;
    this.issueContainer = null;
    contentEl.createEl("h2", { text: t("Connection setup and diagnostics") });
    if (this.saved) {
      contentEl.createEl("p", { text: t("Connection saved. Publishing and automatic sync are off.") });
      new Setting(contentEl).addButton(button => button.setButtonText(t("Close")).onClick(() => this.close()));
      return;
    }
    const titles = ["Confluence target", "Account and token", "Local folders", "Verify and save"];
    contentEl.createEl("p", { text: t("Step {step} of 4: {title}", { step: this.step + 1, title: t(titles[this.step]) }), attr: { "aria-live": "polite" } });
    contentEl.createEl("p", { text: t("Inputs stay in this draft until Save connection. Existing page links are retained.") });
    const text = (name, key, placeholder) => new Setting(contentEl).setName(t(name)).addText(field =>
      field.setValue(this.draft[key]).setPlaceholder(placeholder).setDisabled(this.busy)
        .onChange(value => this.change(key, value)));
    if (this.step === 0) {
      text("Confluence folder URL", "folderUrl", "https://example.atlassian.net/wiki/spaces/DOC/folder/1234");
      contentEl.createEl("p", { text: t("Use a Confluence folder URL, not a page URL. No remote content is created by setup.") });
    } else if (this.step === 1) {
      text("Atlassian email", "email", "name@example.com");
      new Setting(contentEl).setName(t("Confluence API token"))
        .addComponent(el => new SecretComponent(plugin.app, el).setValue(this.draft.secretId)
          .onChange(value => this.change("secretId", value ?? "")));
      contentEl.createEl("p", { text: t("Manage token values in Obsidian SecretStorage. Secret edits there are saved separately, even if this wizard is cancelled.") });
    } else if (this.step === 2) {
      text("Source vault folder", "source", "Project");
      text("Import vault folder", "inbox", "Confluence inbox");
      contentEl.createEl("p", { text: t("The source must exist. Imports use a separate folder; setup does not create folders or change notes.") });
    } else {
      for (const [label, key] of [["Confluence folder URL", "folderUrl"], ["Atlassian email", "email"],
        ["Source vault folder", "source"], ["Import vault folder", "inbox"]]) {
        new Setting(contentEl).setName(t(label)).setDesc(this.draft[key]);
      }
      contentEl.createEl("p", { text: t("The test checks authentication and folder read access only. Publishing permissions are checked when publishing; no test page is created.") });
      new Setting(contentEl).addButton(button => button.setButtonText(t("Run read-only check")).setDisabled(this.busy)
        .onClick(() => this.verify()));
      if (this.verified?.ok) contentEl.createEl("p", { text: t("Read access verified. {count} source Markdown notes found.", { count: this.verified.noteCount }) });
    }
    if (this.busy) contentEl.createEl("p", { text: t("Checking or saving connection…"), attr: { role: "status" } });
    if (this.issue) {
      this.issueContainer = contentEl.createDiv();
      this.issueContainer.createEl("p", { text: t(SETUP_ISSUES[this.issue][0]), attr: { role: "alert" } });
      this.issueContainer.createEl("p", { text: t(SETUP_ISSUES[this.issue][1]) });
    }
    if (this.report) {
      this.reportContainer = contentEl.createDiv();
      this.reportContainer.createEl("p", { text: t("Diagnostics contain versions and check outcomes only. Site, account, paths, connection identifiers, tokens and content are excluded.") });
      this.reportContainer.createEl("pre", { text: JSON.stringify(this.report, null, 2), cls: "cfs-setup-report" });
      new Setting(this.reportContainer).addButton(button => button.setButtonText(t("Copy diagnostics")).setDisabled(this.busy)
        .onClick(async () => {
          try { await navigator.clipboard.writeText(JSON.stringify(this.report, null, 2)); new Notice(t("Redacted diagnostics copied.")); }
          catch { new Notice(t("Could not copy diagnostics. Select the displayed report manually.")); }
        }));
    }
    const navigation = new Setting(contentEl);
    navigation.addButton(button => button.setButtonText(t("Cancel")).onClick(() => this.close()));
    if (this.step > 0) navigation.addButton(button => button.setButtonText(t("Back")).setDisabled(this.busy)
      .onClick(() => { this.step--; this.issue = null; this.render(); }));
    if (this.step < 3) navigation.addButton(button => button.setButtonText(t("Next")).setDisabled(this.busy)
      .onClick(() => this.next()));
    else navigation.addButton(button => button.setButtonText(t("Save connection (read-only)")).setCta()
      .setDisabled(this.busy || !this.verified?.ok).onClick(() => this.save()));
  }

  next() {
    try {
      if (this.step === 0) setupTarget(this.draft);
      else if (this.step === 1) setupAccount(this.app, this.draft);
      else setupFolders(this.app, this.draft);
      this.step++;
      this.issue = null;
    } catch (error) { this.issue = setupIssueCode(error); }
    this.render();
  }

  async verify() {
    this.busy = true;
    this.issue = null;
    this.verified = null;
    this.render();
    const fingerprint = setupFingerprint(this.draft);
    try {
      const result = await this.plugin.testSetup(this.draft, () => this.guard(fingerprint));
      this.guard(fingerprint);
      this.verified = result;
      this.issue = result.checks.find(item => item.status === "fail")?.code;
    } catch (error) { this.issue = setupIssueCode(error); }
    finally {
      this.report = setupDiagnostics(this.plugin, this.verified, this.issue);
      this.busy = false;
      if (this.opened) this.render();
    }
  }

  async save() {
    this.busy = true;
    this.issue = null;
    this.render();
    const fingerprint = setupFingerprint(this.draft);
    try {
      await this.plugin.saveSetup(this.draft, this.verified, this.baseline, expected => this.guard(fingerprint, expected));
      this.saved = true;
      this.onSaved();
    } catch (error) { this.issue = setupIssueCode(error); this.verified = null; }
    finally {
      this.report = setupDiagnostics(this.plugin, this.verified, this.issue);
      this.busy = false;
      if (this.opened) this.render();
    }
  }
}

class SyncDashboard extends Modal {
  constructor(plugin) {
    super(plugin.app);
    this.plugin = plugin;
    this.t = (message, values) => plugin.t(message, values);
    this.pages = [];
    this.versions = [];
    this.status = this.t("Load pages to view their Confluence versions.");
  }

  onOpen() {
    this.opened = true;
    this.contentEl.addClass("cfs-dashboard");
    this.render();
  }

  onClose() {
    this.opened = false;
    this.contentEl.empty();
  }

  render() {
    const { contentEl, t } = this;
    contentEl.empty();
    contentEl.createEl("h2", { text: "Confluence Folder Sync" });
    new Setting(contentEl).setName(t("Connection setup and diagnostics"))
      .addButton(button => button.setButtonText(t("Open setup wizard")).onClick(() => { this.close(); new SetupModal(this.plugin).open(); }));
    contentEl.createEl("p", { text: this.status, attr: { role: "status", "aria-live": "polite" } });
    if (this.plugin.automaticStatus) contentEl.createEl("p", { text: this.plugin.automaticStatus });
    const button = (label, callback, disabled = false) => component =>
      component.setButtonText(t(label)).setDisabled(this.busy || disabled).onClick(callback);
    const command = action => () => {
      this.close();
      void this.plugin.run(action);
    };
    new Setting(contentEl).setName(t("Check and sync"))
      .addButton(button("Preview changes", command("preview")))
      .addButton(button("Import new pages", command("import")))
      .addButton(button("Review publication", command("publish")));
    new Setting(contentEl).setName(t("Download the full folder"))
      .setDesc(t("Save every current page as a new snapshot under the import folder."))
      .addButton(button("Download snapshot", () => this.saveSnapshot()));
    new Setting(contentEl).setName(t("Page versions"))
      .addButton(button("Load pages", () => this.loadPages()));
    new Setting(contentEl).setName(t("Activity and backups"))
      .addButton(button("Open history", () => { this.close(); new HistoryModal(this.plugin).open(); }));

    new Setting(contentEl).setName(t("Connections and recovery"))
      .addButton(button("Manage connections", () => { this.close(); new MappingModal(this.plugin).open(); }));

    if (!this.pages.length) return;
    const selectPage = new Setting(contentEl).setName(t("Confluence page"));
    selectPage.addDropdown(dropdown => {
      this.pageDropdown = dropdown;
      dropdown.setDisabled(this.busy);
      this.filterPages(this.filter ?? "");
      dropdown.onChange(value => {
        this.pageId = value;
        this.versions = [];
        this.difference = null;
        this.review = null;
        this.backup = null;
        this.render();
      });
    });
    new Setting(contentEl).setName(t("Filter pages"))
      .addText(input => input.setValue(this.filter ?? "").setPlaceholder(t("Title or folder"))
        .setDisabled(this.busy).onChange(value => this.filterPages(value)));
    new Setting(contentEl).setName(t("Selected page"))
      .addButton(button("Load versions", () => this.loadVersions(), !this.pageId))
      .addButton(button("Review local application", () => this.loadReview(), !this.pageId))
      .addButton(button("Download latest copy", () => this.saveSnapshot(this.pageId), !this.pageId));
    new Setting(contentEl).setName(t("Conflict resolution"))
      .addButton(button("Resolve text conflict", () => this.resolveConflict(), !this.pageId));
    if (this.versions.length > 1) {
      const version = (field, name) => dropdown => {
        dropdown.setDisabled(this.busy);
        dropdown.selectEl.setAttribute("aria-label", name);
        for (const entry of this.versions) {
          const date = entry.createdAt ? " · " + entry.createdAt.slice(0, 10) : "";
          dropdown.addOption(String(entry.number), "v" + entry.number + date);
        }
        dropdown.setValue(String(this[field])).onChange(value => { this[field] = Number(value); });
      };
      new Setting(contentEl).setName(t("Compare versions"))
        .addDropdown(version("before", t("Base version")))
        .addDropdown(version("after", t("Comparison version")))
        .addButton(button("Compare", () => this.compareVersions()));
    }
    if (this.difference) {
      contentEl.createEl("h3", { text: this.difference.title });
      this.renderDiff(contentEl, this.difference.text.split("\n"), t("Version differences"));
    }
    if (this.review?.hunks.length) {
      const { path, baseVersion, version, hunks } = this.review;
      contentEl.createEl("h3", { text: t("Apply selected changes to {path}", { path }) });
      contentEl.createEl("p", { text: "Confluence v" + baseVersion + " → v" + version });
      for (const [index, hunk] of hunks.entries()) {
        const label = t("Change {number}", { number: index + 1 });
        new Setting(contentEl).setName(label).setDesc(hunk.at === null ?
          t("The local context is missing or ambiguous.") : t("Local line {number}", { number: hunk.at + 1 }))
          .addToggle(toggle => toggle.setDisabled(this.busy || hunk.at === null)
            .setValue(this.selection.has(index)).onChange(enabled => {
              if (enabled) this.selection.add(index);
              else this.selection.delete(index);
              this.applyButton?.setDisabled(this.selection.size === 0);
            }));
        this.renderDiff(contentEl, [
          ...hunk.remove.map(line => "-" + line), ...hunk.insert.map(line => "+" + line),
        ], label);
      }
      new Setting(contentEl).addButton(component => {
        this.applyButton = component;
        button("Apply selected changes", () => this.applyReview(), !this.selection.size)(component);
      });
    }
    if (this.backup) {
      new Setting(contentEl).setName(t("Backup saved"))
        .addButton(button("Open backup", async () => {
          const file = this.app.vault.getFileByPath(this.backup);
          if (file) await this.app.workspace.getLeaf("tab").openFile(file);
          this.close();
        }));
    }
  }

  renderDiff(parent, lines, label) {
    const diff = parent.createEl("pre", { cls: "cfs-diff", attr: { tabindex: "0", "aria-label": label } });
    for (const line of lines) {
      const cls = line.startsWith("+") ? "cfs-added" : line.startsWith("-") ? "cfs-removed" : "";
      diff.createSpan({ text: line + "\n", cls });
    }
  }

  filterPages(text) {
    this.filter = text;
    const term = normalized(text.trim()).toLowerCase();
    const dropdown = this.pageDropdown;
    dropdown.selectEl.replaceChildren();
    dropdown.addOption("", this.t("Choose a page"));
    for (const page of this.pages) {
      if (normalized(page.label).toLowerCase().includes(term) || page.id === this.pageId) {
        dropdown.addOption(page.id, page.label);
      }
    }
    dropdown.setValue(this.pageId ?? "");
  }

  async perform(message, task) {
    if (this.busy) return;
    this.busy = true;
    this.status = this.t(message);
    this.render();
    try {
      await this.plugin.operation(message, task);
    } catch (error) {
      this.status = localizedError(error, this.plugin.language);
    } finally {
      this.busy = false;
      if (this.opened) this.render();
    }
  }

  loadPages() {
    return this.perform("Loading Confluence pages…", async ({ client, folder }) => {
      const remote = await remotePages(client, await client.catalog());
      this.pages = Array.from(remote.trails, ([id, trail]) => ({
        id, label: trail.map(node => node.title).join(" / "),
      })).sort((a, b) => a.label.localeCompare(b.label));
      if (!remote.pages.has(this.pageId)) {
        this.pageId = "";
        this.versions = [];
        this.difference = null;
        this.review = null;
      }
      this.status = this.t("{folder} · {count} pages", { folder: folder.title, count: this.pages.length });
    });
  }

  selected(message, task) {
    const id = this.pageId;
    return this.perform(message, async ({ client, profile }) => {
      const remote = await remotePages(client, await client.catalog());
      const page = remote.pages.get(id);
      if (!page) throw new Error("The selected page is no longer in this Confluence folder.");
      await task(client, page, profile);
    });
  }

  loadVersions() {
    return this.selected("Loading page versions…", async (client, page) => {
      const current = page.version;
      const versions = new Map([[current.number, current]]);
      for (const entry of await client.pageVersions(page.id)) {
        if (Number.isInteger(entry.number) && entry.number > 0) versions.set(entry.number, entry);
      }
      this.versions = Array.from(versions.values()).sort((a, b) => b.number - a.number);
      this.after = this.versions[0].number;
      this.before = this.versions[1]?.number;
      this.difference = null;
      this.status = this.t("{title} · {count} available versions", { title: page.title, count: this.versions.length });
    });
  }

  compareVersions() {
    const before = this.before;
    const after = this.after;
    return this.selected("Comparing page versions…", async (client, page) => {
      if (before === after) throw new Error("Choose two different versions.");
      const url = client.pageUrl(page.id);
      const [oldBody, newBody] = await mapConcurrent([before, after], version => checkedBody(client, page, version));
      const diff = diffLines(fromStorage(oldBody, url), fromStorage(newBody, url));
      this.difference = { title: page.title + " · v" + before + " → v" + after,
        text: diff || this.t("No converted Markdown body difference.") };
      this.status = this.t("Version comparison complete.");
    });
  }

  loadReview() {
    return this.selected("Finding changes that match the local note…", async (client, page, profile) => {
      this.review = null;
      this.backup = null;
      this.review = await prepareLocalReview(this.app, client, profile, page);
      this.selection = new Set();
      const total = this.review.hunks.length;
      const available = this.review.hunks.filter(hunk => hunk.at !== null).length;
      this.status = total ? this.t("{available} of {total} changes match the local note.", { available, total }) :
        this.t("No incoming body changes.");
    });
  }

  resolveConflict() {
    return this.selected("Loading conflict versions…", async (client, page, profile) => {
      const review = await prepareConflict(this.app, client, profile, page);
      if (!this.opened) return;
      this.close();
      new ConflictModal(this.plugin, review).open();
    });
  }

  applyReview() {
    const review = this.review;
    const selection = Array.from(this.selection);
    return this.selected("Checking the selected changes…", async (client, page, profile) => {
      if (!this.opened) return;
      const approved = await this.plugin.confirm(this.t("Apply selected changes"),
        this.t("Apply {count} changes to {path}? A backup will be saved first.", { count: selection.length, path: review.path }),
        this.t("Apply changes"));
      if (!approved || !this.opened) {
        this.status = this.t("Application cancelled.");
        return;
      }
      const result = await applyLocalReview(this.app, client, profile, page, review, selection,
        receipt => this.plugin.recordBackup(receipt));
      this.review = null;
      this.selection = new Set();
      this.backup = result.backup;
      this.status = this.t("{count} changes applied to the local note.", { count: result.count });
    });
  }

  saveSnapshot(id) {
    return this.perform("Preparing the current Confluence snapshot…", async ({ client, folder }) => {
      const remote = await remotePages(client, await client.catalog());
      if (!this.opened) return;
      if (!id) {
        if (!remote.pages.size) throw new Error("The selected folder contains no pages.");
        const approved = await this.plugin.confirm(
          this.t("Download Confluence snapshot"),
          this.t("Save the current versions of {count} pages from {folder} in a new snapshot under {inbox}?",
            { count: remote.pages.size, folder: folder.title, inbox: client.config.inbox }),
          this.t("Download snapshot"),
        );
        if (!approved || !this.opened) {
          this.status = this.t("Snapshot cancelled.");
          return;
        }
      }
      const result = await downloadSnapshot(this.app.vault, client, remote, id);
      this.status = result.summary;
      await this.app.workspace.getLeaf("tab").openFile(result.file);
      if (this.opened) this.close();
      new Notice(result.summary);
    });
  }
}

const DEFAULT_SETTINGS = {
  folderUrl: "", source: "Confluence source", inbox: "Confluence inbox",
  email: "", secretId: "", allowPublish: false, language: "auto",
  autoCheck: false, autoPublish: false, autoMinutes: 5,
  mermaidMode: "code",
};

class Confirmation extends Modal {
  constructor(app, title, summary, buttonLabel, cancelLabel, accept) {
    super(app);
    this.title = title;
    this.summary = summary;
    this.buttonLabel = buttonLabel;
    this.cancelLabel = cancelLabel;
    this.accept = accept;
    this.confirmed = false;
  }

  onOpen() {
    this.contentEl.createEl("h2", { text: this.title });
    this.contentEl.createEl("p", { text: this.summary });
    new Setting(this.contentEl)
      .addButton(button => button.setButtonText(this.cancelLabel).onClick(() => this.close()))
      .addButton(button => button.setButtonText(this.buttonLabel).setCta().onClick(() => {
        this.confirmed = true;
        this.close();
      }));
  }

  onClose() {
    this.contentEl.empty();
    this.accept(this.confirmed);
  }
}

class SyncSettings extends PluginSettingTab {
  constructor(plugin) {
    super(plugin.app, plugin);
    this.plugin = plugin;
  }

  display() {
    const { containerEl, plugin } = this;
    containerEl.empty();
    const settings = plugin.data.settings;
    const t = (message, values) => plugin.t(message, values);
    new Setting(containerEl).setName(t("Connection setup and diagnostics"))
      .setDesc(t("Check a draft connection step by step without publishing or changing notes."))
      .addButton(button => button.setButtonText(t("Open setup wizard")).onClick(() => new SetupModal(plugin, () => this.display()).open()));
    new Setting(containerEl).setName(t("Language"))
      .setDesc(t("Follow Obsidian or choose the language for this plugin."))
      .addDropdown(dropdown => dropdown.addOption("auto", t("Follow Obsidian"))
        .addOption("en", "English").addOption("ko", "한국어").setValue(settings.language)
        .onChange(async value => {
          await plugin.configure("language", value);
          this.display();
        }));
    const text = (name, description, property, placeholder) => {
      new Setting(containerEl).setName(t(name)).setDesc(t(description)).addText(field => {
        field.setValue(settings[property]).setPlaceholder(placeholder).onChange(value => plugin.configure(property, value));
      });
    };
    text("Confluence folder URL", "Copy the URL of a folder from the Confluence sidebar.", "folderUrl", "https://example.atlassian.net/wiki/spaces/DOC/folder/1234");
    text("Atlassian email", "Use the account that issued the Confluence Cloud token.", "email", "name@example.com");
    new Setting(containerEl).setName(t("Confluence API token")).setDesc(t("Select a scoped Atlassian API token stored in Obsidian."))
      .addComponent(el => new SecretComponent(plugin.app, el).setValue(settings.secretId)
        .onChange(value => plugin.configure("secretId", value ?? "")));
    text("Source vault folder", "Publish only notes and referenced files from this folder.", "source", "Project");
    text("Import vault folder", "Save previews and imported copies in a separate folder.", "inbox", "Confluence inbox");
    new Setting(containerEl).setName(t("Mermaid publication"))
      .setDesc(t("Render diagrams locally as PNG and keep their source. Image mode requires manual review; no external renderer is used."))
      .addDropdown(dropdown => dropdown.addOption("code", t("Source code"))
        .addOption("image", t("Local image and source")).setValue(settings.mermaidMode)
        .onChange(async value => { await plugin.configure("mermaidMode", value); this.display(); }));
    new Setting(containerEl).setName(t("Enable publish")).setDesc(t("Allow explicit, confirmed uploads from this vault."))
      .addToggle(toggle => toggle.setValue(settings.allowPublish).onChange(value => plugin.configure("allowPublish", value)));
    new Setting(containerEl).setName(t("Connection")).addButton(button => button.setButtonText(t("Test connection"))
      .onClick(() => plugin.run("connect")));
    new Setting(containerEl).setName(t("Automatic checks"))
      .setDesc(t("Check after source changes and at the selected interval while Obsidian is open. No automatic imports or deletions."))
      .addToggle(toggle => toggle.setValue(settings.autoCheck).onChange(async enabled => {
        await plugin.configure("autoCheck", enabled);
        this.display();
      }));
    new Setting(containerEl).setName(t("Check interval"))
      .addDropdown(dropdown => dropdown.addOption("5", t("5 minutes")).addOption("15", t("15 minutes"))
        .addOption("60", t("60 minutes")).setValue(String(settings.autoMinutes)).setDisabled(!settings.autoCheck)
        .onChange(value => plugin.configure("autoMinutes", Number(value))));
    new Setting(containerEl).setName(t("Automatic publication"))
      .setDesc(t("Upload edits to linked pages only. New notes, moves and conflicts require manual review."))
      .addToggle(toggle => toggle.setValue(settings.autoPublish).setDisabled(!settings.autoCheck || !settings.allowPublish)
        .onChange(async enabled => {
          try {
            const config = enabled ? validatedConfig(settings) : null;
            if (enabled && !await plugin.confirm(t("Enable automatic publication"),
              t("Automatically update linked pages from {source} at {destination} while Obsidian is open?",
                { source: config.source, destination: new URL(config.origin).hostname + " / " + config.folderId }),
              t("Enable automatic publication"))) return;
            await plugin.configure("autoPublish", enabled);
          } catch (error) {
            new Notice(localizedError(error, plugin.language), 12000);
          } finally {
            this.display();
          }
        }));
  }
}

class ConfluenceFolderSync extends Plugin {
  async onload() {
    mermaidRenderers.set(this.app, new LocalMermaid());
    const stored = await this.loadData() ?? {};
    this.data = { settings: { ...DEFAULT_SETTINGS, ...stored.settings }, profiles: stored.profiles ?? {},
      history: Array.isArray(stored.history) ? stored.history : [], backups: Array.isArray(stored.backups) ? stored.backups : [],
      mappingBackups: Array.isArray(stored.mappingBackups) ? stored.mappingBackups : [] };
    this.data.settings.autoCheck = this.data.settings.autoCheck === true;
    this.data.settings.autoPublish = this.data.settings.autoPublish === true && this.data.settings.autoCheck &&
      this.data.settings.allowPublish === true;
    this.saving = Promise.resolve();
    this.renameEvents = [];
    this.registerEvent(this.app.vault.on("rename", (file, oldPath) => {
      this.renameEvents.push({ oldPath, newPath: file.path });
      if (!this.running) void this.applyRenames().catch(error =>
        new Notice(localizedError(error, this.language), 12000));
    }));
    this.addSettingTab(new SyncSettings(this));
    const openDashboard = () => new SyncDashboard(this).open();
    this.ribbon = this.addRibbonIcon("arrow-right-left", this.t("Open Confluence sync dashboard"), openDashboard);
    this.commandDefinitions = [
      { id: "dashboard", name: "Open sync dashboard", callback: openDashboard },
      { id: "setup", name: "Connection setup and diagnostics", callback: () => new SetupModal(this).open() },
      { id: "connections", name: "Connections and recovery", callback: () => new MappingModal(this).open() },
      { id: "history", name: "Activity and backups", callback: () => new HistoryModal(this).open() },
      { id: "publish", name: "Publish vault folder to Confluence", callback: () => this.run("publish") },
      { id: "preview", name: "Preview Confluence changes", callback: () => this.run("preview") },
      { id: "import", name: "Import new Confluence pages", callback: () => this.run("import") },
    ];
    this.registerCommands();
    this.automatic = new AutomaticSync(this);
    for (const event of ["create", "modify", "delete"]) {
      this.registerEvent(this.app.vault.on(event, file => this.automatic.changed(file)));
    }
    this.registerEvent(this.app.vault.on("rename", (file, oldPath) => this.automatic.changed(file, oldPath)));
    this.register(() => this.automatic.dispose());
    this.app.workspace.onLayoutReady(() => this.automatic.configure());
  }

  get language() {
    return syncLanguage(this.data.settings.language, typeof getLanguage === "function" ? getLanguage() : "en");
  }

  onunload() {
    this.unloaded = true;
    this.automatic?.dispose();
    mermaidRenderers.get(this.app)?.dispose();
  }

  t(message, values) {
    return translate(this.language, message, values);
  }

  registerCommands() {
    for (const command of this.commandDefinitions) {
      if (this.commandsRegistered) this.removeCommand(command.id);
      this.addCommand({ ...command, name: this.t(command.name) });
    }
    this.commandsRegistered = true;
    this.ribbon.setAttribute("aria-label", this.t("Open Confluence sync dashboard"));
  }

  persist() {
    const snapshot = structuredClone(this.data);
    const saved = this.saving.catch(() => {}).then(() => this.saveData(snapshot));
    this.saving = saved;
    return saved;
  }

  applyRenames() {
    if (this.applyingRenames) return this.applyingRenames;
    if (!this.renameEvents.length) return Promise.resolve();
    this.applyingRenames = (async () => {
      while (this.renameEvents.length) {
        const event = this.renameEvents[0];
        const previous = structuredClone(this.data.profiles);
        try {
          for (const [key, profile] of Object.entries(this.data.profiles)) {
            // A configured-root rename is transferred explicitly in management,
            // preserving the old baseline and folder ownership until confirmation.
            const sourceRoot = mappingProfileKey(key)?.[2];
            if (sourceRoot && pathIn(sourceRoot, event.oldPath)) continue;
            try {
              rekeySource(profile, event.oldPath, event.newPath);
            } catch (error) {
              if (error.code !== "RENAME_COLLISION") throw error;
              profile.renameConflicts ??= [];
              profile.renameConflicts = profile.renameConflicts.filter(item => item.to !== event.oldPath);
              profile.renameConflicts.push({ from: error.from, to: event.newPath });
              new Notice(localizedError(error, this.language), 12000);
            }
          }
          await this.persist();
          this.renameEvents.shift();
        } catch (error) {
          this.data.profiles = previous;
          throw error;
        }
      }
    })().finally(() => { this.applyingRenames = null; });
    return this.applyingRenames;
  }

  async configure(key, value) {
    if (this.setupSaving) {
      new Notice(this.t("Wait until connection settings finish saving."));
      return;
    }
    this.data.settings[key] = value;
    if (["folderUrl", "source", "email", "secretId", "mermaidMode"].includes(key) ||
        (key === "allowPublish" && !value) || (key === "autoCheck" && !value)) {
      this.data.settings.autoPublish = false;
    }
    try {
      await this.persist();
      if (key === "language") this.registerCommands();
      this.automatic?.configure();
    } catch {
      new Notice(this.t("Confluence Folder Sync could not save the settings."));
    }
  }

  confirm(title, summary, button) {
    return new Promise(resolve => new Confirmation(this.app, title, summary, button, this.t("Cancel"), resolve).open());
  }

  testSetup(draft, check) {
    return this.exclusive(() => verifySetup(this.app, draft,
      (config, token, guard) => new ConfluenceCloud(config, token, requestUrl, { check: guard }), check));
  }

  saveSetup(draft, verified, baseline, check) {
    return this.exclusive(() => commitSetup(this, draft, verified, baseline, check));
  }

  async exclusive(task) {
    if (this.unloaded) throw new Error("The plugin is disabled. Reopen it before continuing.");
    if (this.running) throw new Error("A Confluence command is already running in this vault.");
    await this.applyRenames();
    if (this.running) throw new Error("A Confluence command is already running in this vault.");
    this.running = true;
    try {
      await this.saving.catch(() => this.persist());
      return await task();
    } finally {
      this.running = false;
      await this.applyRenames();
    }
  }

  withConnection(task, options = {}) {
    return this.exclusive(async () => {
      const config = validatedConfig({ ...this.data.settings, language: this.language });
      config.checkPreparation = () => {
        if (this.unloaded) {
          const error = new Error("The operation was cancelled. Completed changes are preserved.");
          error.name = "AbortError";
          throw error;
        }
      };
      const token = this.app.secretStorage.getSecret(config.secretId);
      if (!token) throw new Error("Choose a valid token in the plugin settings.");
      const client = new ConfluenceCloud(config, token, requestUrl, {
        check: () => {
          if (this.unloaded) {
            const error = new Error("The operation was cancelled. Completed changes are preserved.");
            error.name = "AbortError";
            throw error;
          }
        },
        onWait: milliseconds => new Notice(this.t("Confluence is busy. Waiting {seconds} seconds before retrying a read.",
          { seconds: Math.ceil(milliseconds / 1000) }), 5000),
      });
      const folder = await client.connect();
      const key = publicationTarget(config);
      const profile = this.data.profiles[key] ??= { folders: {}, pages: {}, imports: {} };
      if (profile.movedTo && !options.management) throw new Error("This source profile was migrated. Use its destination source or migrate it back.");
      return task({ client, folder, config, profile, save: () => this.persist() });
    });
  }

  async recordOperation(action, task) {
    const item = { id: crypto.randomUUID(), time: new Date().toISOString(), action, status: "Running" };
    this.data.history.push(item);
    this.data.history = this.data.history.slice(-100);
    await this.persist();
    try {
      const result = await task();
      item.status = "Succeeded";
      if (typeof result === "number") item.count = result;
      return result;
    } catch (error) {
      item.status = error?.name === "AbortError" ? "Cancelled" : "Failed";
      item.error = localizedError(error, this.language).slice(0, 600);
      throw error;
    } finally {
      item.finished = new Date().toISOString();
      if (!this.unloaded) await this.persist();
    }
  }

  operation(action, task, options) {
    return this.withConnection(context => this.recordOperation(action, () => task(context)), options);
  }

  async recordBackup(receipt) {
    this.data.backups.push(receipt);
    this.data.backups = this.data.backups.slice(-100);
    await this.persist();
  }

  preparePublication() {
    return this.withConnection(async ({ client, profile }) => {
      const tree = await preparedNotes(this.app, client.config, () => client.check?.());
      return publicationReview(this.app, client, profile, tree, await client.catalog());
    });
  }

  async run(action) {
    const progress = new Notice(this.t("Connecting to Confluence…"), 0);
    try {
      await this.operation(action === "publish" ? "Review publication" : action === "preview" ? "Preview changes" :
        action === "import" ? "Import new pages" : "Test connection", async ({ client, folder, config, profile, save }) => {
        if (action === "connect") {
          new Notice(this.t("Connected to Confluence folder {title} ({id}).", { title: folder.title, id: config.folderId }));
          return;
        }
        const catalog = await client.catalog();
        if (action !== "publish") {
          const result = await incoming(this.app, client, catalog, profile, save, action === "import");
          await this.app.workspace.getLeaf("tab").openFile(result.file);
          new Notice(result.summary);
          return;
        }
        const tree = await preparedNotes(this.app, config, () => client.check?.());
        const review = await publicationReview(this.app, client, profile, tree, catalog);
        new PublicationModal(this, review).open();
      });
    } catch (error) {
      const message = localizedError(error, this.language);
      new Notice("Confluence Folder Sync: " + message, 12000);
    } finally {
      progress.hide();
    }
  }
}

module.exports = ConfluenceFolderSync;
